"""Reorder sales against a close clone's visible schedule."""

import itertools


_TEACHER_CLONE12_RANK_BASE = (
    _adaptive_teacher_bundle_clone24_hire_guard_milk3_entrypoint
)
_TEACHER_CLONE12_RANK_FALLBACK = _rank_sell_slots
_TEACHER_CLONE12_RANK_DISTANCE = 12
_TEACHER_CLONE12_RANK_MINIMUM_GAIN = 20
_TEACHER_CLONE12_RANK_MAX_ORDERS = 6


def _teacher_clone12_sale_orders(action):
    return [
        list(order)
        for order in action.get("market") or []
        if _is_sell(order)
    ]


def _teacher_clone12_predicted_revenue(
    observation,
    candidate_orders,
    opponent_orders,
    available,
):
    market = _get(observation, "market", {}) or {}
    inventory = {
        str(key): int(value or 0)
        for key, value in dict(_get(market, "inventory", {}) or {}).items()
    }
    candidate_remaining = [max(0, int(order[2] or 0)) for order in candidate_orders]
    opponent_remaining = [max(0, int(order[2] or 0)) for order in opponent_orders]
    revenue = 0
    for index in range(max(len(candidate_orders), len(opponent_orders))):
        while True:
            candidate = candidate_orders[index] if index < len(candidate_orders) else None
            opponent = opponent_orders[index] if index < len(opponent_orders) else None
            candidate_item = candidate[1] if candidate is not None else None
            opponent_item = opponent[1] if opponent is not None else None
            candidate_ok = bool(
                candidate is not None
                and candidate_remaining[index] > 0
                and available.get(candidate_item, 0) > 0
            )
            opponent_ok = bool(
                opponent is not None and opponent_remaining[index] > 0
            )
            if not candidate_ok and not opponent_ok:
                break
            candidate_price = (
                _market_price(candidate_item, inventory.get(candidate_item, 0))
                if candidate_ok
                else None
            )
            opponent_price = (
                _market_price(opponent_item, inventory.get(opponent_item, 0))
                if opponent_ok
                else None
            )
            if candidate_ok:
                candidate_remaining[index] -= 1
                available[candidate_item] -= 1
                revenue += candidate_price
            if opponent_ok:
                opponent_remaining[index] -= 1
            if candidate_price is not None and candidate_price > 1:
                inventory[candidate_item] = inventory.get(candidate_item, 0) + 1
            if opponent_price is not None and opponent_price > 1:
                inventory[opponent_item] = inventory.get(opponent_item, 0) + 1
    return revenue


def _rank_sell_slots(observation, action, configuration):
    fallback = _TEACHER_CLONE12_RANK_FALLBACK(
        observation,
        action,
        configuration,
    )
    if _clone_distance(observation) > _TEACHER_CLONE12_RANK_DISTANCE:
        return fallback
    candidate_orders = _teacher_clone12_sale_orders(fallback)
    if not 2 <= len(candidate_orders) <= _TEACHER_CLONE12_RANK_MAX_ORDERS:
        return fallback
    step = min(max(0, int(_get(observation, "step", 0) or 0)), 719)
    tape = _kawa_actions(observation)
    if step >= len(tape):
        return fallback
    predicted = _TEACHER_CLONE12_RANK_FALLBACK(
        observation,
        _copy_action(tape[step]),
        configuration,
    )
    opponent_orders = _teacher_clone12_sale_orders(predicted)
    if not opponent_orders:
        return fallback
    projected = _projected_shed(observation, fallback)
    encoded = tuple(tuple(order) for order in candidate_orders)
    current_revenue = _teacher_clone12_predicted_revenue(
        observation,
        candidate_orders,
        opponent_orders,
        dict(projected),
    )
    best_revenue = current_revenue
    best_orders = candidate_orders
    for permutation in sorted(set(itertools.permutations(encoded))):
        orders = [list(order) for order in permutation]
        revenue = _teacher_clone12_predicted_revenue(
            observation,
            orders,
            opponent_orders,
            dict(projected),
        )
        if revenue > best_revenue:
            best_revenue = revenue
            best_orders = orders
    if best_revenue - current_revenue <= _TEACHER_CLONE12_RANK_MINIMUM_GAIN:
        return fallback
    ranked = iter(best_orders)
    fallback["market"] = [
        next(ranked) if _is_sell(order) else order
        for order in fallback.get("market") or []
    ]
    return fallback


