"""Rank existing sales with public, identity-free opponent supply signals."""


_OBSERVED_CYCLE_BASE = (
    _adaptive_teacher_bundle_clone24_hire_guard_milkroute3_clone8_rank_entrypoint
)
_OBSERVED_CYCLE_PRODUCTS = tuple(_SELLABLE)
_OBSERVED_CYCLE_EXACT_PRODUCTS = tuple(
    item for item in _OBSERVED_CYCLE_PRODUCTS if item not in ("WHEAT", "FERTILIZER")
)
_OBSERVED_CYCLE_EWMA_DECAY = 0.8
_OBSERVED_CYCLE_VISIBLE_WEIGHT = 0.25
_OBSERVED_CYCLE_EWMA_WEIGHT = 1.0
_OBSERVED_CYCLE_DAY_LAG_WEIGHT = 1.0
_OBSERVED_CYCLE_STATE = {0: {}, 1: {}}


def _observed_cycle_new_state():
    return {
        "last_step": -1,
        "inventory": {},
        "own_sells": {},
        "shops": (),
        "history": {},
        "ewma": {item: 0.0 for item in _OBSERVED_CYCLE_PRODUCTS},
    }


def _observed_cycle_state(observation, step):
    seat = _seat(observation)
    state = _OBSERVED_CYCLE_STATE[seat]
    if step == 0 or step < int(state.get("last_step", -1)):
        state = _observed_cycle_new_state()
        _OBSERVED_CYCLE_STATE[seat] = state
    return state


def _observed_cycle_town_drain(step, shops, item):
    drain = int(item != "FERTILIZER" and step % 24 == 0)
    if step % 4 != 0:
        return drain
    for shop in shops or ():
        products = _SHOP_PRODUCTS.get(shop, ())
        if item in products:
            drain += 2 if len(products) == 1 else 1
    return drain


def _observed_cycle_update(observation, step):
    state = _observed_cycle_state(observation, step)
    market = _get(observation, "market", {}) or {}
    current = {
        str(item): int(value or 0)
        for item, value in dict(_get(market, "inventory", {}) or {}).items()
    }
    previous = dict(state.get("inventory", {}) or {})
    previous_step = int(state.get("last_step", -1))
    inferred = {item: 0.0 for item in _OBSERVED_CYCLE_PRODUCTS}
    if previous and previous_step == step - 1:
        own_sells = dict(state.get("own_sells", {}) or {})
        shops = tuple(state.get("shops", ()) or ())
        for item in _OBSERVED_CYCLE_EXACT_PRODUCTS:
            delta = current.get(item, 10000) - previous.get(item, 10000)
            quantity = (
                delta
                + _observed_cycle_town_drain(previous_step, shops, item)
                - int(own_sells.get(item, 0) or 0)
            )
            inferred[item] = float(max(0, quantity))
        state["history"][previous_step] = inferred
        cutoff = previous_step - 48
        state["history"] = {
            key: value
            for key, value in state["history"].items()
            if key >= cutoff
        }
        for item in _OBSERVED_CYCLE_PRODUCTS:
            state["ewma"][item] = (
                _OBSERVED_CYCLE_EWMA_DECAY * state["ewma"].get(item, 0.0)
                + (1.0 - _OBSERVED_CYCLE_EWMA_DECAY) * inferred[item]
            )
    state["last_step"] = step
    state["inventory"] = current
    town = _get(observation, "town", {}) or {}
    state["shops"] = tuple(_get(town, "unlocked_shops", []) or [])
    return state


def _observed_cycle_visible_supply(observation):
    seat = _seat(observation)
    farms = list(_get(observation, "farms", []) or [])
    opponent = farms[1 - seat] if len(farms) >= 2 else {}
    exposure = {item: 0.0 for item in _OBSERVED_CYCLE_PRODUCTS}
    products = {"COW": "MILK", "SHEEP": "WOOL", "GOOSE": "EGG"}
    for row in _get(opponent, "tiles", []) or []:
        for tile in row if isinstance(row, list) else [row]:
            if not isinstance(tile, dict):
                continue
            crop = str(tile.get("crop", "") or "").upper()
            if crop in exposure:
                exposure[crop] += max(
                    1.0,
                    float(tile.get("yield_units", 0) or 0),
                )
            animal = str(tile.get("animal", "") or "").upper()
            product = products.get(animal)
            if product:
                exposure[product] += 1.0 + max(
                    0.0,
                    float(tile.get("yield_units", 0) or 0),
                )
            if tile.get("fertilizer_available", False):
                exposure["FERTILIZER"] += 1.0
    return exposure


def _observed_cycle_rank_sales(observation, action, state, step):
    result = _copy_action(action)
    market = list(result.get("market") or [])
    if sum(_is_sell(order) for order in market) < 2:
        return result
    visible = _observed_cycle_visible_supply(observation)
    cycle = dict(state.get("history", {}).get(step - 24, {}) or {})
    ewma = dict(state.get("ewma", {}) or {})
    rows = []
    for index, order in enumerate(market):
        if not _is_sell(order):
            continue
        item = str(order[1])
        pressure = (
            _OBSERVED_CYCLE_VISIBLE_WEIGHT * float(visible.get(item, 0.0) or 0.0)
            + _OBSERVED_CYCLE_EWMA_WEIGHT * float(ewma.get(item, 0.0) or 0.0)
            + _OBSERVED_CYCLE_DAY_LAG_WEIGHT * float(cycle.get(item, 0.0) or 0.0)
        )
        rows.append(
            (
                _impact_score(observation, order) * (1.0 + pressure),
                -index,
                list(order),
            )
        )
    rows.sort(reverse=True)
    ranked = iter(row[2] for row in rows)
    result["market"] = [
        next(ranked) if _is_sell(order) else order
        for order in market
    ]
    return result


def _observed_cycle_record_own_sells(observation, action, state):
    remaining = _projected_shed(observation, action)
    sold = {item: 0 for item in _OBSERVED_CYCLE_PRODUCTS}
    for order in action.get("market", []) or []:
        if not _is_sell(order):
            continue
        item = str(order[1])
        requested = max(0, int(order[2] or 0))
        quantity = min(requested, max(0, int(remaining.get(item, 0) or 0)))
        sold[item] += quantity
        remaining[item] = max(0, int(remaining.get(item, 0) or 0) - quantity)
    state["own_sells"] = sold


def _adaptive_observed_cycle_mix_rank_entrypoint(observation):
    step = min(max(0, int(_get(observation, "step", 0) or 0)), 719)
    state = _observed_cycle_update(observation, step)
    action = _OBSERVED_CYCLE_BASE(observation)
    action = _observed_cycle_rank_sales(observation, action, state, step)
    _observed_cycle_record_own_sells(observation, action, state)
    return action

"""Front-run planned fertilizer sales when the public farms remain similar."""


_FERTILIZER_PREEMPT_BASE = _adaptive_observed_cycle_mix_rank_entrypoint
_FERTILIZER_PREEMPT_FUTURE_SELLS = _future_sells
_FERTILIZER_PREEMPT_MAX_DISTANCE = 24
_FERTILIZER_PREEMPT_MIN_QUANTITY = 4
