"""Lead planned premium sales on one strong prior-day observation."""


_CYCLE_NOCLONE_LEAD2_DAY1_MIN4_BASE = (
    _adaptive_observed_cycle_fertilizer_preempt_entrypoint
)
_CYCLE_NOCLONE_LEAD2_DAY1_MIN4_PREEMPT = _preempt_shift
_CYCLE_NOCLONE_PRODUCTS = ("STRAWBERRY", "MELON", "MILK", "WOOL")
_CYCLE_NOCLONE_HORIZON = 2
_CYCLE_NOCLONE_MIN_OBSERVED = 4.0


def _cycle_noclone_pressure(observation, step, item):
    state = _OBSERVED_CYCLE_STATE.get(_seat(observation), {}) or {}
    history = state.get("history", {}) or {}
    return float((history.get(step - 24, {}) or {}).get(item, 0.0) or 0.0)


def _preempt_shift(observation, action, step):
    result = _CYCLE_NOCLONE_LEAD2_DAY1_MIN4_PREEMPT(observation, action, step)
    if not (_PREEMPT_START <= step < _PREEMPT_STOP):
        return result
    state = _shift_state(observation, step)
    if state.get("due") or _clone_distance(observation) <= _PREEMPT_MAX_CLONE_DISTANCE:
        return result
    market = [list(order) for order in result.get("market", []) or []]
    if len(market) >= 10:
        return result
    remaining = _projected_shed(observation, result)
    for order in market:
        if _is_sell(order):
            item = str(order[1])
            remaining[item] = max(
                0,
                int(remaining.get(item, 0) or 0) - max(0, int(order[2] or 0)),
            )
    actions = _kawa_actions(observation)
    shifted = {}
    for item in _CYCLE_NOCLONE_PRODUCTS:
        if _cycle_noclone_pressure(observation, step, item) < _CYCLE_NOCLONE_MIN_OBSERVED:
            continue
        planned = 0
        for ahead in range(1, _CYCLE_NOCLONE_HORIZON + 1):
            if step + ahead >= len(actions):
                break
            planned += sum(
                max(0, int(order[2] or 0))
                for order in actions[step + ahead].get("market", []) or []
                if _is_sell(order) and str(order[1]) == item
            )
        target = min(
            max(0, int(remaining.get(item, 0) or 0)),
            planned,
            _PREEMPT_MAX_BATCH,
        )
        if planned < _PREEMPT_MIN_FUTURE_QUANTITY or target <= 0 or len(market) >= 10:
            continue
        market.append(["SELL", item, target])
        remaining[item] = max(0, int(remaining.get(item, 0) or 0) - target)
        shifted[item] = target
    if shifted:
        result = _copy_action(result)
        result["market"] = market[:10]
        state["due_step"] = step + 1
        state["due"] = shifted
    return result


def _adaptive_cycle_noclone_lead2_day1_min4_entrypoint(observation):
    return _CYCLE_NOCLONE_LEAD2_DAY1_MIN4_BASE(observation)

