"""Cancel a sale-delay bundle when same-clock rival supply repeats."""


_NOCLONE_CYCLE_VETO_BASE = (
    _adaptive_cycle_noclone_terminal_force_drop_entrypoint
)
_NOCLONE_CYCLE_VETO_ROUTE_DELAY = (
    _BUNDLED_NOCLONE_CYCLE_VETO_ROUTE_DELAY
)
_NOCLONE_CYCLE_VETO_ROUTE_NAMESPACE = (
    _NOCLONE_CYCLE_VETO_ROUTE_DELAY.__globals__
)
_NOCLONE_CYCLE_VETO_MIN_SHOPS = 3
_NOCLONE_CYCLE_VETO_MIN_PRODUCTS = 3
_NOCLONE_CYCLE_VETO_TERMINAL_START = 696
_NOCLONE_CYCLE_VETO_HISTORY_STEPS = 192
_NOCLONE_CYCLE_VETO_LAGS = (24, 48, 72)
_NOCLONE_CYCLE_VETO_MIN_POSITIVE_LAGS = 2
_NOCLONE_CYCLE_VETO_PRODUCTS = tuple(_SELLABLE)
_NOCLONE_CYCLE_VETO_STATE = {0: {}, 1: {}}


def _noclone_cycle_veto_shops(shops):
    return tuple(str(shop).upper() for shop in (shops or ()))


def _noclone_cycle_veto_products(shops):
    sellable = set(_SELLABLE)
    return {
        str(item).upper()
        for shop in _noclone_cycle_veto_shops(shops)
        for item in _SHOP_PRODUCTS.get(shop, ())
        if str(item).upper() in sellable
    }


def _noclone_cycle_veto_enabled(shops):
    normalized = _noclone_cycle_veto_shops(shops)
    if len(normalized) < _NOCLONE_CYCLE_VETO_MIN_SHOPS:
        return False
    products = _noclone_cycle_veto_products(
        normalized[:_NOCLONE_CYCLE_VETO_MIN_SHOPS]
    )
    return len(products) >= _NOCLONE_CYCLE_VETO_MIN_PRODUCTS


def _noclone_cycle_veto_new_state():
    return {
        "last_step": -1,
        "inventory": {},
        "shops": (),
        "own_supply": {},
        "history": {},
    }


def _noclone_cycle_veto_seat_state(observation, step):
    seat = _seat(observation)
    state = _NOCLONE_CYCLE_VETO_STATE.setdefault(
        seat,
        _noclone_cycle_veto_new_state(),
    )
    if not isinstance(state, dict) or not state:
        state = _noclone_cycle_veto_new_state()
        _NOCLONE_CYCLE_VETO_STATE[seat] = state
    last_step = int(state.get("last_step", -1))
    if step == 0 or step < last_step:
        state = _noclone_cycle_veto_new_state()
        _NOCLONE_CYCLE_VETO_STATE[seat] = state
    return seat, state


def _noclone_cycle_veto_town_drain(step, shops, item):
    demand = int(item != "FERTILIZER" and step % 24 == 0)
    if step % 4 != 0:
        return demand
    for shop in shops or ():
        products = _SHOP_PRODUCTS.get(str(shop).upper(), ())
        if item in products:
            demand += 2 if len(products) == 1 else 1
    return demand


def _noclone_cycle_veto_observe(observation, step):
    _seat_index, state = _noclone_cycle_veto_seat_state(observation, step)
    market = _get(observation, "market", {}) or {}
    current = {
        str(item).upper(): int(value or 0)
        for item, value in dict(_get(market, "inventory", {}) or {}).items()
    }
    previous = dict(state.get("inventory", {}) or {})
    previous_step = int(state.get("last_step", -1))
    history = dict(state.get("history", {}) or {})
    if previous and previous_step == step - 1:
        own_supply = dict(state.get("own_supply", {}) or {})
        shops = tuple(state.get("shops", ()) or ())
        inferred = {}
        for item in _NOCLONE_CYCLE_VETO_PRODUCTS:
            if item not in previous or item not in current:
                inferred[item] = 0
                continue
            delta = current[item] - previous[item]
            net_supply = (
                delta
                + _noclone_cycle_veto_town_drain(
                    previous_step,
                    shops,
                    item,
                )
                - int(own_supply.get(item, 0) or 0)
            )
            # WHEAT and FERTILIZER can be bought from the shared market.  A
            # positive value is still a causal lower bound on rival supply.
            inferred[item] = max(0, int(net_supply))
        history[previous_step] = inferred
    cutoff = step - _NOCLONE_CYCLE_VETO_HISTORY_STEPS
    state["history"] = {
        key: value for key, value in history.items() if int(key) >= cutoff
    }
    state["last_step"] = step
    state["inventory"] = current
    town = _get(observation, "town", {}) or {}
    state["shops"] = _noclone_cycle_veto_shops(
        _get(town, "unlocked_shops", []) or []
    )
    return state


def _noclone_cycle_veto_record_final_action(observation, action, state):
    projected = _projected_shed(observation, action)
    remaining = {
        str(item).upper(): max(0, int(quantity or 0))
        for item, quantity in dict(projected or {}).items()
    }
    market = _get(observation, "market", {}) or {}
    prices = {
        str(item).upper(): float(value or 0)
        for item, value in dict(_get(market, "prices", {}) or {}).items()
    }
    supplied = {}
    for raw_order in action.get("market", []) or []:
        order = list(raw_order)
        if not _is_sell(order):
            continue
        item = str(order[1]).upper()
        requested = max(0, int(order[2] or 0))
        quantity = min(requested, remaining.get(item, 0))
        remaining[item] = max(0, remaining.get(item, 0) - quantity)
        if quantity > 0 and prices.get(item, 1.0) > 1.0:
            supplied[item] = supplied.get(item, 0) + quantity
    state["own_supply"] = supplied


def _noclone_cycle_veto_due_orders(observation, step):
    namespace = _NOCLONE_CYCLE_VETO_ROUTE_NAMESPACE
    seat = namespace["_seat"](observation)
    state = namespace["_POST_FLOW_STATE"].get(seat)
    if not isinstance(state, dict):
        return seat, []
    last_step = int(state.get("last_step", -1) or -1)
    if step == 0 or step < last_step:
        return seat, []
    if int(state.get("due_step", -1) or -1) != step:
        return seat, []
    return seat, [list(order) for order in state.get("orders", []) or []]


def _noclone_cycle_veto_market_before_shift(action, due_orders):
    current = [list(order) for order in action.get("market", []) or []]
    if not due_orders:
        return current
    return _NOCLONE_CYCLE_VETO_ROUTE_NAMESPACE["_post_flow_merge_orders"](
        due_orders,
        current,
    )


def _noclone_cycle_veto_order_key(order):
    return tuple(order) if isinstance(order, (list, tuple)) else (order,)


def _noclone_cycle_veto_keep_supported(
    result,
    market_before_shift,
    pending_orders,
    supported_products,
):
    namespace = _NOCLONE_CYCLE_VETO_ROUTE_NAMESPACE
    supported = set(supported_products or ())
    retained = [
        list(order)
        for order in pending_orders
        if namespace["_is_sell"](order)
        and str(order[1]).upper() in supported
    ]
    delayed_counts = {}
    for order in retained:
        key = _noclone_cycle_veto_order_key(order)
        delayed_counts[key] = delayed_counts.get(key, 0) + 1

    final_market = []
    for raw_order in market_before_shift:
        order = list(raw_order)
        key = _noclone_cycle_veto_order_key(order)
        if delayed_counts.get(key, 0) > 0:
            delayed_counts[key] -= 1
            continue
        final_market.append(order)

    final = namespace["_copy_action"](result)
    final["market"] = final_market[:10]
    return final, retained


def _noclone_cycle_veto_repeated_bundle_supply(
    history,
    step,
    pending_orders,
):
    items = {
        str(order[1]).upper()
        for order in pending_orders
        if _is_sell(order)
    }
    for item in items:
        positive_lags = sum(
            int(
                int(
                    (history.get(step - lag, {}) or {}).get(item, 0) or 0
                )
                > 0
            )
            for lag in _NOCLONE_CYCLE_VETO_LAGS
        )
        if positive_lags >= _NOCLONE_CYCLE_VETO_MIN_POSITIVE_LAGS:
            return True
    return False


def _noclone_cycle_veto_apply(
    observation,
    action,
    enabled,
    supported_products,
    ledger_state,
):
    namespace = _NOCLONE_CYCLE_VETO_ROUTE_NAMESPACE
    step = int(_get(observation, "step", 0) or 0)
    seat, due_orders = _noclone_cycle_veto_due_orders(observation, step)
    market_before_shift = _noclone_cycle_veto_market_before_shift(
        action,
        due_orders,
    )

    original_threshold = namespace["_POST_FLOW_THRESHOLD"]
    try:
        if not enabled:
            namespace["_POST_FLOW_THRESHOLD"] = -1.0
        result = _NOCLONE_CYCLE_VETO_ROUTE_DELAY(observation, action)
    finally:
        namespace["_POST_FLOW_THRESHOLD"] = original_threshold

    state = namespace["_POST_FLOW_STATE"][seat]
    pending_orders = [list(order) for order in state.get("orders", []) or []]
    proposed_delay = (
        enabled
        and int(state.get("due_step", -1) or -1) == step + 1
        and bool(pending_orders)
    )
    if proposed_delay:
        result, retained = _noclone_cycle_veto_keep_supported(
            result,
            market_before_shift,
            pending_orders,
            supported_products,
        )
        veto = bool(retained) and _noclone_cycle_veto_repeated_bundle_supply(
            ledger_state.get("history", {}) or {},
            step,
            retained,
        )
        if veto:
            result = namespace["_copy_action"](result)
            result["market"] = [
                list(order) for order in market_before_shift[:10]
            ]
            retained = []
        state["orders"] = retained
        state["due_step"] = step + 1 if retained else -1

    namespace["_post_flow_record_transition"](
        observation,
        result,
        state,
        step,
    )
    return result


def _adaptive_cycle_noclone_terminal_force_drop_route_delay_product_breadth_cycle_veto_entrypoint(
    observation,
):
    step = min(max(0, int(_get(observation, "step", 0) or 0)), 719)
    ledger_state = _noclone_cycle_veto_observe(observation, step)
    action = _NOCLONE_CYCLE_VETO_BASE(observation)
    if step >= _NOCLONE_CYCLE_VETO_TERMINAL_START:
        _noclone_cycle_veto_record_final_action(
            observation,
            action,
            ledger_state,
        )
        return action
    town = _get(observation, "town", {}) or {}
    shops = list(_get(town, "unlocked_shops", []) or [])
    enabled = _noclone_cycle_veto_enabled(shops)
    result = _noclone_cycle_veto_apply(
        observation,
        action,
        enabled,
        _noclone_cycle_veto_products(shops),
        ledger_state,
    )
    _noclone_cycle_veto_record_final_action(
        observation,
        result,
        ledger_state,
    )
    return result

"""Latch a public sheep-yield route hypothesis at the second shop."""


_YARN_LATE_SHEEP_GAP_PARENT = (
    _adaptive_cycle_noclone_terminal_force_drop_route_delay_product_breadth_cycle_veto_entrypoint
)
_YARN_LATE_SHEEP_GAP_PARENT_LABEL = _kawa_route_label
_YARN_LATE_SHEEP_GAP_FIRST = "6c12s_4q_first_yarn"
_YARN_LATE_SHEEP_GAP_SECOND = "6c12s_4q_second_yarn"
_YARN_LATE_SHEEP_GAP_KEEP_PARENT = "KEEP_PARENT"
_YARN_LATE_SHEEP_GAP_GATE_SHOP = {
    0: "BRUNCH_SPOT",
    1: "ICE_CREAM_SHOP",
}
_YARN_LATE_SHEEP_GAP_DECISION = {0: None, 1: None}
_YARN_LATE_SHEEP_GAP_LAST_STEP = {0: -1, 1: -1}


def _yarn_late_sheep_gap_reset(seat, step):
    last_step = int(_YARN_LATE_SHEEP_GAP_LAST_STEP.get(seat, -1))
    if step == 0 or step < last_step:
        _YARN_LATE_SHEEP_GAP_DECISION[seat] = None
    _YARN_LATE_SHEEP_GAP_LAST_STEP[seat] = step


def _yarn_late_sheep_gap_visible_shops(observation):
    town = _get(observation, "town", {}) or {}
    return tuple(
        str(shop).upper()
        for shop in (_get(town, "unlocked_shops", []) or [])
    )


def _yarn_late_sheep_gap_yield(farm):
    total = 0
    for row in (_get(farm, "tiles", []) or []):
        for tile in row if isinstance(row, list) else [row]:
            if not isinstance(tile, dict):
                continue
            if str(tile.get("animal", "") or "").upper() != "SHEEP":
                continue
            total += int(tile.get("yield_units", 0) or 0)
    return total


def _yarn_late_sheep_gap_prefers_second(observation, seat):
    farms = list(_get(observation, "farms", []) or [])
    own = farms[seat] if seat < len(farms) else {}
    rival_seat = 1 - seat
    rival = farms[rival_seat] if rival_seat < len(farms) else {}
    own_yield = _yarn_late_sheep_gap_yield(own)
    rival_yield = _yarn_late_sheep_gap_yield(rival)
    return rival_yield > own_yield


def _kawa_route_label(observation):
    step = int(_get(observation, "step", 0) or 0)
    seat = _seat(observation)
    _yarn_late_sheep_gap_reset(seat, step)

    decision = _YARN_LATE_SHEEP_GAP_DECISION.get(seat)
    if decision == _YARN_LATE_SHEEP_GAP_SECOND:
        return _YARN_LATE_SHEEP_GAP_SECOND
    if decision == _YARN_LATE_SHEEP_GAP_KEEP_PARENT:
        return _YARN_LATE_SHEEP_GAP_PARENT_LABEL(observation)

    parent_label = _YARN_LATE_SHEEP_GAP_PARENT_LABEL(observation)
    shops = _yarn_late_sheep_gap_visible_shops(observation)
    if len(shops) < 2:
        return parent_label

    decision = _YARN_LATE_SHEEP_GAP_KEEP_PARENT
    gate_holds = (
        parent_label == _YARN_LATE_SHEEP_GAP_FIRST
        and shops[1] == _YARN_LATE_SHEEP_GAP_GATE_SHOP[seat]
    )
    if gate_holds and _yarn_late_sheep_gap_prefers_second(observation, seat):
        decision = _YARN_LATE_SHEEP_GAP_SECOND
    _YARN_LATE_SHEEP_GAP_DECISION[seat] = decision
    if decision == _YARN_LATE_SHEEP_GAP_SECOND:
        return _YARN_LATE_SHEEP_GAP_SECOND
    return parent_label


def _adaptive_cycle_noclone_terminal_force_drop_route_delay_product_breadth_cycle_veto_yarn_late_sheep_gap_entrypoint(
    observation,
):
    """Return the frozen BDD502 action after latched route resolution."""
    return _YARN_LATE_SHEEP_GAP_PARENT(observation)

"""Move the best terminal sale first when public farms otherwise match."""


_TERMINAL_SYMMETRY_FIRST_IMPACT_PARENT = _adaptive_cycle_noclone_terminal_force_drop_route_delay_product_breadth_cycle_veto_yarn_late_sheep_gap_entrypoint
_TERMINAL_SYMMETRY_FIRST_IMPACT_START = 696


def _terminal_symmetry_farm_without_money(farm):
    """Return every public farm field except cash, or None for bad input."""
    if isinstance(farm, dict):
        return {key: value for key, value in farm.items() if key != "money"}
    items = getattr(farm, "items", None)
    if not callable(items):
        return None
    try:
        return {key: value for key, value in items() if key != "money"}
    except (TypeError, ValueError):
        return None


def _terminal_symmetry_public_farms_equal(observation):
    farms = _get(observation, "farms", []) or []
    if not isinstance(farms, (list, tuple)) or len(farms) != 2:
        return False
    left = _terminal_symmetry_farm_without_money(farms[0])
    right = _terminal_symmetry_farm_without_money(farms[1])
    return left is not None and right is not None and left == right


def _terminal_symmetry_first_impact(observation, action):
    market = _get(action, "market", []) or []
    if not isinstance(market, (list, tuple)):
        return action
    sell_slots = [
        index
        for index, order in enumerate(market)
        if isinstance(order, (list, tuple)) and list(order[:1]) == ["SELL"]
    ]
    if len(sell_slots) < 2:
        return action

    sales = [market[index] for index in sell_slots]
    scores = [_impact_score(observation, order) for order in sales]
    best = max(range(len(sales)), key=scores.__getitem__)
    if best == 0:
        return action

    reranked = [sales[best], *sales[:best], *sales[best + 1 :]]
    result = _copy_action(action)
    for index, order in zip(sell_slots, reranked):
        result["market"][index] = list(order)
    return result


def _adaptive_cycle_noclone_terminal_force_drop_route_delay_product_breadth_cycle_veto_yarn_late_sheep_gap_terminal_symmetry_first_impact_entrypoint(
    observation,
):
    """Return sheep-gap, changing only symmetric terminal SELL-slot order."""
    action = _TERMINAL_SYMMETRY_FIRST_IMPACT_PARENT(observation)
    step = min(max(0, int(_get(observation, "step", 0) or 0)), 719)
    if step < _TERMINAL_SYMMETRY_FIRST_IMPACT_START:
        return action
    if not _terminal_symmetry_public_farms_equal(observation):
        return action
    return _terminal_symmetry_first_impact(observation, action)

"""Add the cash-breadth veto and one exact terminal sale deferral."""

import copy as _V14_TERMINAL_DEBT_COPY
import math as _CASH_BREADTH_ABSTAIN_MATH


_CASH_BREADTH_ABSTAIN_PARENT = _adaptive_cycle_noclone_terminal_force_drop_route_delay_product_breadth_cycle_veto_yarn_late_sheep_gap_terminal_symmetry_first_impact_entrypoint
_CASH_BREADTH_ABSTAIN_PARENT_APPLY = _noclone_cycle_veto_apply
_CASH_BREADTH_ABSTAIN_ROUTE_NAMESPACE = _NOCLONE_CYCLE_VETO_ROUTE_NAMESPACE
_CASH_BREADTH_ABSTAIN_SHOP_COUNT = 3
_CASH_BREADTH_ABSTAIN_MIN_PRODUCTS = 6
_CASH_BREADTH_ABSTAIN_MISSING = object()


def _cash_breadth_abstain_money(farm):
    raw = _get(farm, "money", _CASH_BREADTH_ABSTAIN_MISSING)
    if (
        raw is _CASH_BREADTH_ABSTAIN_MISSING
        or isinstance(raw, bool)
        or not isinstance(raw, (int, float))
    ):
        return None
    parsed = float(raw)
    if not _CASH_BREADTH_ABSTAIN_MATH.isfinite(parsed):
        return None
    return parsed


def _cash_breadth_abstain_public_gate(observation):
    """Use only current public shops, seat, and farm cash."""
    town = _get(observation, "town", {}) or {}
    shops = _get(town, "unlocked_shops", []) or []
    if not isinstance(shops, (list, tuple)):
        return False
    first_shops = list(shops[:_CASH_BREADTH_ABSTAIN_SHOP_COUNT])
    if len(first_shops) < _CASH_BREADTH_ABSTAIN_SHOP_COUNT:
        return False
    products = _noclone_cycle_veto_products(first_shops)
    if len(products) < _CASH_BREADTH_ABSTAIN_MIN_PRODUCTS:
        return False

    farms = _get(observation, "farms", _CASH_BREADTH_ABSTAIN_MISSING)
    if not isinstance(farms, (list, tuple)) or len(farms) < 2:
        return False
    seat = _seat(observation)
    own_money = _cash_breadth_abstain_money(farms[seat])
    rival_money = _cash_breadth_abstain_money(farms[1 - seat])
    if own_money is None or rival_money is None:
        return False
    return own_money <= rival_money


def _cash_breadth_abstain_defer_transition(*_args, **_kwargs):
    """Let the wrapper record the action after its one possible veto."""
    return


def _cash_breadth_abstain_existing_future_debt(namespace, seat, step):
    state = namespace["_POST_FLOW_STATE"].get(seat)
    if not isinstance(state, dict):
        return False
    try:
        due_step = int(state.get("due_step", -1) or -1)
    except (TypeError, ValueError):
        return False
    return due_step == step + 1 and bool(state.get("orders", []) or [])


def _noclone_cycle_veto_apply(
    observation,
    action,
    enabled,
    supported_products,
    ledger_state,
):
    namespace = _CASH_BREADTH_ABSTAIN_ROUTE_NAMESPACE
    step = int(_get(observation, "step", 0) or 0)
    seat, due_orders = _noclone_cycle_veto_due_orders(observation, step)
    market_before_shift = _noclone_cycle_veto_market_before_shift(
        action,
        due_orders,
    )
    had_future_debt = _cash_breadth_abstain_existing_future_debt(
        namespace,
        seat,
        step,
    )

    record_transition = namespace["_post_flow_record_transition"]
    try:
        namespace["_post_flow_record_transition"] = (
            _cash_breadth_abstain_defer_transition
        )
        result = _CASH_BREADTH_ABSTAIN_PARENT_APPLY(
            observation,
            action,
            enabled,
            supported_products,
            ledger_state,
        )
    finally:
        namespace["_post_flow_record_transition"] = record_transition

    state = namespace["_POST_FLOW_STATE"][seat]
    pending_orders = [list(order) for order in state.get("orders", []) or []]
    proposed_delay = (
        enabled
        and not had_future_debt
        and int(state.get("due_step", -1) or -1) == step + 1
        and bool(pending_orders)
    )
    if proposed_delay and _cash_breadth_abstain_public_gate(observation):
        result = namespace["_copy_action"](result)
        result["market"] = [list(order) for order in market_before_shift]
        state["orders"] = []
        state["due_step"] = -1

    record_transition(
        observation,
        result,
        state,
        step,
    )
    return result


_V14_TERMINAL_DEBT_DEFER_STEP = 696
_V14_TERMINAL_DEBT_DUE_STEP = 713
_V14_TERMINAL_DEBT_MAX_ORDERS = 10
_V14_TERMINAL_DEBT_PRODUCTS = frozenset(("CARROT", "WOOL"))
_V14_TERMINAL_DEBT_STATE = {}


def _v14_terminal_debt_new_state(last_step=-1):
    return {"last_step": last_step, "due_step": -1, "orders": []}


def _v14_terminal_debt_positive_order(order, product=None):
    """Accept only an engine-shaped, positive target-product sale."""
    if not isinstance(order, list) or len(order) < 3:
        return False
    if order[0] != "SELL" or order[1] not in _V14_TERMINAL_DEBT_PRODUCTS:
        return False
    if product is not None and order[1] != product:
        return False
    quantity = order[2]
    return not isinstance(quantity, bool) and isinstance(quantity, int) and quantity > 0


def _v14_terminal_debt_state_is_valid(state):
    if not isinstance(state, dict):
        return False
    if set(state) != {"last_step", "due_step", "orders"}:
        return False
    last_step = state["last_step"]
    due_step = state["due_step"]
    orders = state["orders"]
    if (
        isinstance(last_step, bool)
        or not isinstance(last_step, int)
        or last_step < -1
        or isinstance(due_step, bool)
        or not isinstance(due_step, int)
        or not isinstance(orders, list)
    ):
        return False
    if due_step == -1:
        return not orders
    return (
        due_step == _V14_TERMINAL_DEBT_DUE_STEP
        and bool(orders)
        and all(_v14_terminal_debt_positive_order(order) for order in orders)
    )


def _v14_terminal_debt_context(observation, step):
    """Return selected-seat state and whether this call may alter an action."""
    player = _get(observation, "player", 0)
    if isinstance(player, bool) or not isinstance(player, int) or player not in (0, 1):
        return None, None, False
    seat = player
    state = _V14_TERMINAL_DEBT_STATE.get(seat)
    if state is None:
        state = _v14_terminal_debt_new_state()
        _V14_TERMINAL_DEBT_STATE[seat] = state
        return seat, state, True
    if not _v14_terminal_debt_state_is_valid(state):
        _V14_TERMINAL_DEBT_STATE[seat] = _v14_terminal_debt_new_state(step)
        return seat, _V14_TERMINAL_DEBT_STATE[seat], False
    if step == 0 or step <= state["last_step"]:
        _V14_TERMINAL_DEBT_STATE[seat] = _v14_terminal_debt_new_state(step)
        return seat, _V14_TERMINAL_DEBT_STATE[seat], False
    if state["due_step"] != -1 and step > state["due_step"]:
        _V14_TERMINAL_DEBT_STATE[seat] = _v14_terminal_debt_new_state(step)
        return seat, _V14_TERMINAL_DEBT_STATE[seat], False
    return seat, state, True


def _v14_terminal_debt_defer(observation, action, state):
    product = "CARROT" if _terminal_symmetry_public_farms_equal(observation) else "WOOL"
    market = _get(action, "market", None)
    if not isinstance(market, list):
        return action

    deferred = []
    retained = []
    for order in market:
        if (
            isinstance(order, list)
            and len(order) >= 2
            and order[0] == "SELL"
            and order[1] == product
        ):
            if not _v14_terminal_debt_positive_order(order, product):
                return action
            deferred.append(_V14_TERMINAL_DEBT_COPY.deepcopy(order))
        else:
            retained.append(_V14_TERMINAL_DEBT_COPY.deepcopy(order))
    if not deferred:
        return action

    result = _V14_TERMINAL_DEBT_COPY.deepcopy(action)
    result["market"] = retained
    state["due_step"] = _V14_TERMINAL_DEBT_DUE_STEP
    state["orders"] = deferred
    return result


def _v14_terminal_debt_repay(action, state):
    orders = _V14_TERMINAL_DEBT_COPY.deepcopy(state["orders"])
    state["orders"] = []
    state["due_step"] = -1
    market = _get(action, "market", None)
    if not isinstance(market, list):
        return action
    result = _V14_TERMINAL_DEBT_COPY.deepcopy(action)
    result["market"] = [
        *orders,
        *_V14_TERMINAL_DEBT_COPY.deepcopy(market),
    ][:_V14_TERMINAL_DEBT_MAX_ORDERS]
    return result


def _adaptive_v14_cash_terminal_debt_entrypoint(observation):
    """Return Round 13 plus cash breadth and exact terminal sale debt."""
    action = _CASH_BREADTH_ABSTAIN_PARENT(observation)
    try:
        step = _get(observation, "step", 0)
        if isinstance(step, bool) or not isinstance(step, int) or step < 0:
            return action
        _seat_id, state, usable = _v14_terminal_debt_context(observation, step)
        if state is None:
            return action
        if not usable:
            return action
        if step == _V14_TERMINAL_DEBT_DEFER_STEP:
            if state["due_step"] == -1:
                action = _v14_terminal_debt_defer(observation, action, state)
        elif (
            step == _V14_TERMINAL_DEBT_DUE_STEP
            and state["due_step"] == step
            and state["orders"]
        ):
            action = _v14_terminal_debt_repay(action, state)
        state["last_step"] = step
        return action
    except (TypeError, ValueError, OverflowError, KeyError, IndexError):
        return action

"""Cap each selected terminal-debt sale bundle at four units."""

_V15_TERMINAL_DEBT_CAP4_PARENT = _adaptive_v14_cash_terminal_debt_entrypoint
_V15_TERMINAL_DEBT_CAP4_PARENT_DEFER = _v14_terminal_debt_defer
_V15_TERMINAL_DEBT_MAX_QUANTITY = 4


def _v15_terminal_debt_cap4_defer(observation, action, state):
    """Use the parent defer only when every selected sale is small enough."""
    product = "CARROT" if _terminal_symmetry_public_farms_equal(observation) else "WOOL"
    market = _get(action, "market", None)
    if isinstance(market, list):
        for order in market:
            selected = (
                isinstance(order, list)
                and len(order) >= 2
                and order[0] == "SELL"
                and order[1] == product
            )
            if not selected:
                continue
            if (
                _v14_terminal_debt_positive_order(order, product)
                and order[2] > _V15_TERMINAL_DEBT_MAX_QUANTITY
            ):
                return action
    return _V15_TERMINAL_DEBT_CAP4_PARENT_DEFER(observation, action, state)


_v14_terminal_debt_defer = _v15_terminal_debt_cap4_defer


def _adaptive_v15_terminal_debt_cap4_entrypoint(observation):
    """Return the frozen Round-14 policy with the terminal debt cap."""
    return _V15_TERMINAL_DEBT_CAP4_PARENT(observation)

"""Use public shop breadth to cap debt and small inner debt to gate MILK."""

import copy as _V15_BREADTH_CAP4_INNER_MILK_COPY


_V15_BREADTH_CAP4_INNER_MILK_PARENT = (
    _adaptive_v15_terminal_debt_cap4_entrypoint
)
_V15_BREADTH_CAP4_INNER_MILK_PARENT_DEFER = (
    _V15_TERMINAL_DEBT_CAP4_PARENT_DEFER
)
_V15_BREADTH_CAP4_INNER_MILK_DEFER_STEP = 696
_V15_BREADTH_CAP4_INNER_MILK_DUE_STEP = 713
_V15_BREADTH_CAP4_INNER_MILK_SHOP_COUNT = 3
_V15_BREADTH_CAP4_INNER_MILK_BLOCK_BREADTH = 6
_V15_BREADTH_CAP4_INNER_MILK_MAX_QUANTITY = 4
_V15_BREADTH_CAP4_INNER_MILK_MAX_ORDERS = 10
_V15_BREADTH_CAP4_INNER_MILK_PRODUCT = "MILK"
_V15_BREADTH_CAP4_INNER_MILK_STATE = {}
_V15_BREADTH_CAP4_INNER_MILK_CURRENT_INNER = {}


def _v15_breadth_cap4_inner_milk_public_breadth(observation):
    """Return first-three public-shop product breadth, or None if malformed."""
    town = _get(observation, "town", None)
    shops = _get(town, "unlocked_shops", None)
    if not isinstance(shops, (list, tuple)):
        return None
    first_shops = list(shops[:_V15_BREADTH_CAP4_INNER_MILK_SHOP_COUNT])
    if len(first_shops) != _V15_BREADTH_CAP4_INNER_MILK_SHOP_COUNT:
        return None
    normalized_shops = []
    for shop in first_shops:
        if not isinstance(shop, str) or not shop or shop != shop.strip():
            return None
        normalized = shop.upper()
        if normalized not in _SHOP_PRODUCTS:
            return None
        normalized_shops.append(normalized)
    products = _noclone_cycle_veto_products(normalized_shops)
    if not isinstance(products, set):
        return None
    return len(products)


def _v15_breadth_cap4_inner_milk_parent_defer(observation, action, state):
    """Block a large parent bundle only on verified broad public shops."""
    product = "CARROT" if _terminal_symmetry_public_farms_equal(observation) else "WOOL"
    market = _get(action, "market", None)
    if not isinstance(market, list):
        return action

    has_large_selected_bundle = False
    for order in market:
        selected = (
            isinstance(order, list)
            and len(order) >= 2
            and order[0] == "SELL"
            and order[1] == product
        )
        if not selected:
            continue
        if not _v14_terminal_debt_positive_order(order, product):
            return action
        if order[2] > _V15_BREADTH_CAP4_INNER_MILK_MAX_QUANTITY:
            has_large_selected_bundle = True

    if has_large_selected_bundle:
        breadth = _v15_breadth_cap4_inner_milk_public_breadth(observation)
        if breadth is None or breadth >= _V15_BREADTH_CAP4_INNER_MILK_BLOCK_BREADTH:
            return action
    result = _V15_BREADTH_CAP4_INNER_MILK_PARENT_DEFER(
        observation,
        action,
        state,
    )
    player = _get(observation, "player", 0)
    step = _get(observation, "step", 0)
    if (
        not isinstance(player, bool)
        and isinstance(player, int)
        and player in (0, 1)
        and not isinstance(step, bool)
        and isinstance(step, int)
        and step == _V15_BREADTH_CAP4_INNER_MILK_DEFER_STEP
        and _v14_terminal_debt_state_is_valid(state)
        and state["due_step"] == _V15_BREADTH_CAP4_INNER_MILK_DUE_STEP
        and state["orders"]
    ):
        _V15_BREADTH_CAP4_INNER_MILK_CURRENT_INNER[player] = (step, state)
    return result


_v14_terminal_debt_defer = _v15_breadth_cap4_inner_milk_parent_defer


def _v15_breadth_cap4_inner_milk_new_state(last_step=-1):
    return {"last_step": last_step, "due_step": -1, "orders": []}


def _v15_breadth_cap4_inner_milk_positive_order(order):
    """Accept only an engine-shaped, positive MILK sale."""
    if not isinstance(order, list) or len(order) < 3:
        return False
    if order[0] != "SELL" or order[1] != _V15_BREADTH_CAP4_INNER_MILK_PRODUCT:
        return False
    quantity = order[2]
    return not isinstance(quantity, bool) and isinstance(quantity, int) and quantity > 0


def _v15_breadth_cap4_inner_milk_state_is_valid(state):
    if not isinstance(state, dict):
        return False
    if set(state) != {"last_step", "due_step", "orders"}:
        return False
    last_step = state["last_step"]
    due_step = state["due_step"]
    orders = state["orders"]
    if (
        isinstance(last_step, bool)
        or not isinstance(last_step, int)
        or last_step < -1
        or isinstance(due_step, bool)
        or not isinstance(due_step, int)
        or not isinstance(orders, list)
    ):
        return False
    if due_step == -1:
        return not orders
    return (
        due_step == _V15_BREADTH_CAP4_INNER_MILK_DUE_STEP
        and bool(orders)
        and all(
            _v15_breadth_cap4_inner_milk_positive_order(order)
            for order in orders
        )
    )


def _v15_breadth_cap4_inner_milk_context(observation, step):
    """Return isolated seat state and whether this call may alter the action."""
    player = _get(observation, "player", 0)
    if isinstance(player, bool) or not isinstance(player, int) or player not in (0, 1):
        return None, None, False
    seat = player
    if step == 0:
        _V15_BREADTH_CAP4_INNER_MILK_STATE[seat] = (
            _v15_breadth_cap4_inner_milk_new_state(0)
        )
        return seat, _V15_BREADTH_CAP4_INNER_MILK_STATE[seat], False

    state = _V15_BREADTH_CAP4_INNER_MILK_STATE.get(seat)
    if state is None:
        state = _v15_breadth_cap4_inner_milk_new_state()
        _V15_BREADTH_CAP4_INNER_MILK_STATE[seat] = state
        return seat, state, True
    if not _v15_breadth_cap4_inner_milk_state_is_valid(state):
        _V15_BREADTH_CAP4_INNER_MILK_STATE[seat] = (
            _v15_breadth_cap4_inner_milk_new_state(step)
        )
        return seat, _V15_BREADTH_CAP4_INNER_MILK_STATE[seat], False
    if step <= state["last_step"]:
        _V15_BREADTH_CAP4_INNER_MILK_STATE[seat] = (
            _v15_breadth_cap4_inner_milk_new_state(step)
        )
        return seat, _V15_BREADTH_CAP4_INNER_MILK_STATE[seat], False
    if state["due_step"] != -1 and step > state["due_step"]:
        _V15_BREADTH_CAP4_INNER_MILK_STATE[seat] = (
            _v15_breadth_cap4_inner_milk_new_state(step)
        )
        return seat, _V15_BREADTH_CAP4_INNER_MILK_STATE[seat], False
    return seat, state, True


def _v15_breadth_cap4_inner_milk_public_farms_not_equal(observation):
    """Reject malformed farms and use the frozen public-farm equality test."""
    farms = _get(observation, "farms", None)
    if not isinstance(farms, (list, tuple)) or len(farms) != 2:
        return False
    left = _terminal_symmetry_farm_without_money(farms[0])
    right = _terminal_symmetry_farm_without_money(farms[1])
    if left is None or right is None:
        return False
    return not _terminal_symmetry_public_farms_equal(observation)


def _v15_breadth_cap4_inner_milk_has_small_inner_debt(seat):
    """Require exact live parent debt with every bundle at most four."""
    state = _V14_TERMINAL_DEBT_STATE.get(seat)
    marker = _V15_BREADTH_CAP4_INNER_MILK_CURRENT_INNER.get(seat)
    if (
        not isinstance(marker, tuple)
        or len(marker) != 2
        or marker[0] != _V15_BREADTH_CAP4_INNER_MILK_DEFER_STEP
        or marker[1] is not state
    ):
        return False
    if not _v14_terminal_debt_state_is_valid(state):
        return False
    if (
        state["due_step"] != _V15_BREADTH_CAP4_INNER_MILK_DUE_STEP
        or not state["orders"]
    ):
        return False
    return all(
        order[2] <= _V15_BREADTH_CAP4_INNER_MILK_MAX_QUANTITY
        for order in state["orders"]
    )


def _v15_breadth_cap4_inner_milk_defer(action, state):
    market = _get(action, "market", None)
    if not isinstance(market, list):
        return action

    deferred = []
    retained = []
    for order in market:
        selected = (
            isinstance(order, list)
            and len(order) >= 2
            and order[0] == "SELL"
            and order[1] == _V15_BREADTH_CAP4_INNER_MILK_PRODUCT
        )
        if selected:
            if not _v15_breadth_cap4_inner_milk_positive_order(order):
                return action
            deferred.append(_V15_BREADTH_CAP4_INNER_MILK_COPY.deepcopy(order))
        else:
            retained.append(_V15_BREADTH_CAP4_INNER_MILK_COPY.deepcopy(order))
    if not deferred:
        return action

    result = _V15_BREADTH_CAP4_INNER_MILK_COPY.deepcopy(action)
    result["market"] = retained
    state["due_step"] = _V15_BREADTH_CAP4_INNER_MILK_DUE_STEP
    state["orders"] = deferred
    return result


def _v15_breadth_cap4_inner_milk_repay(action, state):
    orders = _V15_BREADTH_CAP4_INNER_MILK_COPY.deepcopy(state["orders"])
    state["orders"] = []
    state["due_step"] = -1
    market = _get(action, "market", None)
    if not isinstance(market, list):
        return action
    result = _V15_BREADTH_CAP4_INNER_MILK_COPY.deepcopy(action)
    result["market"] = [
        *orders,
        *_V15_BREADTH_CAP4_INNER_MILK_COPY.deepcopy(market),
    ][:_V15_BREADTH_CAP4_INNER_MILK_MAX_ORDERS]
    return result


def _adaptive_v15_breadth_cap4_inner_milk_entrypoint(observation):
    """Return breadth-gated parent debt plus exact inner-gated MILK debt."""
    marker_seat = _get(observation, "player", 0)
    if (
        not isinstance(marker_seat, bool)
        and isinstance(marker_seat, int)
        and marker_seat in (0, 1)
    ):
        _V15_BREADTH_CAP4_INNER_MILK_CURRENT_INNER.pop(marker_seat, None)
    else:
        marker_seat = None
    action = _V15_BREADTH_CAP4_INNER_MILK_PARENT(observation)
    try:
        step = _get(observation, "step", 0)
        if isinstance(step, bool) or not isinstance(step, int) or step < 0:
            return action
        seat, state, usable = _v15_breadth_cap4_inner_milk_context(
            observation,
            step,
        )
        if state is None or not usable:
            return action
        if step == _V15_BREADTH_CAP4_INNER_MILK_DEFER_STEP:
            if (
                state["due_step"] == -1
                and _v15_breadth_cap4_inner_milk_public_farms_not_equal(observation)
                and _v15_breadth_cap4_inner_milk_has_small_inner_debt(seat)
            ):
                action = _v15_breadth_cap4_inner_milk_defer(action, state)
        elif (
            step == _V15_BREADTH_CAP4_INNER_MILK_DUE_STEP
            and state["due_step"] == step
            and state["orders"]
        ):
            action = _v15_breadth_cap4_inner_milk_repay(action, state)
        state["last_step"] = step
        return action
    except (TypeError, ValueError, OverflowError, KeyError, IndexError, AttributeError):
        return action
    finally:
        if marker_seat is not None:
            _V15_BREADTH_CAP4_INNER_MILK_CURRENT_INNER.pop(marker_seat, None)

"""Disable first-YARN route delay only from verified original shop data."""


_V16_FIRST_YARN_ROUTE_DELAY_ABSTAIN_V2_PARENT = (
    _adaptive_v15_breadth_cap4_inner_milk_entrypoint
)
_V16_FIRST_YARN_ROUTE_DELAY_ABSTAIN_V2_PARENT_ENABLED = (
    _noclone_cycle_veto_enabled
)
_V16_FIRST_YARN_ROUTE_DELAY_ABSTAIN_V2_SHOP = "YARN_STORE"
_V16_FIRST_YARN_ROUTE_DELAY_ABSTAIN_V2_CONTEXT = []


def _v16_first_yarn_route_delay_abstain_v2_normalized_shops(shops):
    """Return exact known normalized shops, or None for malformed input."""
    if not isinstance(shops, (list, tuple)):
        return None
    normalized = []
    for shop in shops:
        if not isinstance(shop, str) or not shop or shop != shop.strip():
            return None
        name = shop.upper()
        if name not in _SHOP_PRODUCTS:
            return None
        normalized.append(name)
    return tuple(normalized)


def _v16_first_yarn_route_delay_abstain_v2_original_context(observation):
    """Validate the untouched public unlocked-shop value without coercion."""
    try:
        town = _get(observation, "town", None)
        if town is None:
            return None
        shops = _get(town, "unlocked_shops", None)
        return _v16_first_yarn_route_delay_abstain_v2_normalized_shops(shops)
    except (TypeError, ValueError, KeyError, AttributeError):
        return None


def _v16_first_yarn_route_delay_abstain_v2_enabled(shops):
    """Preserve the parent unless verified original and passed shops match."""
    parent_enabled = _V16_FIRST_YARN_ROUTE_DELAY_ABSTAIN_V2_PARENT_ENABLED(
        shops
    )
    if not _V16_FIRST_YARN_ROUTE_DELAY_ABSTAIN_V2_CONTEXT:
        return parent_enabled
    original = _V16_FIRST_YARN_ROUTE_DELAY_ABSTAIN_V2_CONTEXT[-1]
    if not original:
        return parent_enabled
    normalized = _v16_first_yarn_route_delay_abstain_v2_normalized_shops(shops)
    if normalized != original:
        return parent_enabled
    if original[0] == _V16_FIRST_YARN_ROUTE_DELAY_ABSTAIN_V2_SHOP:
        return False
    return parent_enabled


_noclone_cycle_veto_enabled = (
    _v16_first_yarn_route_delay_abstain_v2_enabled
)


def _adaptive_v16_first_yarn_route_delay_abstain_v2_entrypoint(observation):
    """Run the frozen parent under exact original public-shop context."""
    context = _v16_first_yarn_route_delay_abstain_v2_original_context(
        observation
    )
    _V16_FIRST_YARN_ROUTE_DELAY_ABSTAIN_V2_CONTEXT.append(context)
    try:
        return _V16_FIRST_YARN_ROUTE_DELAY_ABSTAIN_V2_PARENT(observation)
    finally:
        _V16_FIRST_YARN_ROUTE_DELAY_ABSTAIN_V2_CONTEXT.pop()

"""Repair two public route-debt sequences without changing other routes."""

import copy as _V17_ROUTE_DEBT_REPAIR_COPY


_V17_ROUTE_DEBT_REPAIR_PARENT = (
    _adaptive_v16_first_yarn_route_delay_abstain_v2_entrypoint
)
_V17_ROUTE_DEBT_REPAIR_PARENT_APPLY = _noclone_cycle_veto_apply
_V17_ROUTE_DEBT_REPAIR_PARENT_TERMINAL_DEFER = _v14_terminal_debt_defer
_V17_ROUTE_DEBT_REPAIR_ROUTE_NAMESPACE = (
    _NOCLONE_CYCLE_VETO_ROUTE_NAMESPACE
)
_V17_ROUTE_DEBT_REPAIR_STATIC80_SHOPS = (
    "BAKERY",
    "BAKERY",
    "PIZZA_SHOP",
)
_V17_ROUTE_DEBT_REPAIR_STATIC80_CAPTURE_STEP = 256
_V17_ROUTE_DEBT_REPAIR_STATIC80_DUE_STEP = 672
_V17_ROUTE_DEBT_REPAIR_STATIC80_VETO_STEPS = (264, 576, 608)
_V17_ROUTE_DEBT_REPAIR_STATIC80_ORDER = ["SELL", "WHEAT", 6]
_V17_ROUTE_DEBT_REPAIR_STATIC89_ROUTE_STEP = 672
_V17_ROUTE_DEBT_REPAIR_STATIC89_TERMINAL_STEP = 696
_V17_ROUTE_DEBT_REPAIR_STATIC89_FIRST_SHOP = "PET_CAFE"
_V17_ROUTE_DEBT_REPAIR_MAX_MARKET_ORDERS = 10
_V17_ROUTE_DEBT_REPAIR_CROPS = (
    "WHEAT",
    "CARROT",
    "TOMATO",
    "STRAWBERRY",
    "MELON",
)
_V17_ROUTE_DEBT_REPAIR_ANIMALS = ("GOOSE", "COW", "SHEEP")
_V17_ROUTE_DEBT_REPAIR_BUY_PRODUCTS = ("WHEAT", "FERTILIZER")
_V17_ROUTE_DEBT_REPAIR_MISSING = object()
_V17_ROUTE_DEBT_REPAIR_STATE = {}
_V17_ROUTE_DEBT_REPAIR_CONTEXT = []


def _v17_route_debt_repair_new_state(last_step=-1, continuous=False):
    return {
        "last_step": last_step,
        "continuous": continuous,
        "static80_due_step": -1,
        "static80_orders": [],
        "static89_latch": False,
    }


def _v17_route_debt_repair_exact_wheat_order(order):
    return (
        isinstance(order, list)
        and len(order) == 3
        and order[0] == "SELL"
        and order[1] == "WHEAT"
        and not isinstance(order[2], bool)
        and isinstance(order[2], int)
        and order[2] == 6
    )


def _v17_route_debt_repair_held_is_exact(state):
    return (
        isinstance(state, dict)
        and state.get("static80_due_step")
        == _V17_ROUTE_DEBT_REPAIR_STATIC80_DUE_STEP
        and isinstance(state.get("static80_orders"), list)
        and len(state["static80_orders"]) == 1
        and _v17_route_debt_repair_exact_wheat_order(
            state["static80_orders"][0]
        )
    )


def _v17_route_debt_repair_state_is_valid(state):
    if not isinstance(state, dict):
        return False
    if set(state) != {
        "last_step",
        "continuous",
        "static80_due_step",
        "static80_orders",
        "static89_latch",
    }:
        return False
    last_step = state["last_step"]
    due_step = state["static80_due_step"]
    orders = state["static80_orders"]
    if (
        isinstance(last_step, bool)
        or not isinstance(last_step, int)
        or last_step < -1
        or not isinstance(state["continuous"], bool)
        or isinstance(due_step, bool)
        or not isinstance(due_step, int)
        or not isinstance(orders, list)
        or not isinstance(state["static89_latch"], bool)
    ):
        return False
    if due_step == -1:
        return not orders
    return _v17_route_debt_repair_held_is_exact(state)


def _v17_route_debt_repair_clear_static80(state):
    state["static80_due_step"] = -1
    state["static80_orders"] = []


def _v17_route_debt_repair_clear_payload(state):
    _v17_route_debt_repair_clear_static80(state)
    state["static89_latch"] = False


def _v17_route_debt_repair_seat(observation):
    player = _get(
        observation,
        "player",
        _V17_ROUTE_DEBT_REPAIR_MISSING,
    )
    if isinstance(player, bool) or not isinstance(player, int):
        return None
    return player if player in (0, 1) else None


def _v17_route_debt_repair_step(observation):
    step = _get(
        observation,
        "step",
        _V17_ROUTE_DEBT_REPAIR_MISSING,
    )
    if isinstance(step, bool) or not isinstance(step, int):
        return None
    return step if 0 <= step <= 719 else None


def _v17_route_debt_repair_normalized_shops(observation):
    """Validate the untouched public shop sequence without coercion."""
    try:
        town = _get(observation, "town", None)
        if town is None:
            return None
        shops = _get(town, "unlocked_shops", None)
        if not isinstance(shops, (list, tuple)):
            return None
        normalized = []
        for shop in shops:
            if not isinstance(shop, str) or not shop or shop != shop.strip():
                return None
            name = shop.upper()
            if name not in _SHOP_PRODUCTS:
                return None
            normalized.append(name)
        return tuple(normalized)
    except (TypeError, ValueError, KeyError, AttributeError):
        return None


def _v17_route_debt_repair_static80_gate(shops):
    return (
        isinstance(shops, tuple)
        and shops[:3] == _V17_ROUTE_DEBT_REPAIR_STATIC80_SHOPS
    )


def _v17_route_debt_repair_static89_gate(shops):
    return (
        isinstance(shops, tuple)
        and bool(shops)
        and shops[0] == _V17_ROUTE_DEBT_REPAIR_STATIC89_FIRST_SHOP
    )


def _v17_route_debt_repair_prepare_context(observation):
    seat = _v17_route_debt_repair_seat(observation)
    step = _v17_route_debt_repair_step(observation)
    shops = _v17_route_debt_repair_normalized_shops(observation)
    if seat is None:
        _V17_ROUTE_DEBT_REPAIR_STATE.clear()
        return {
            "observation": observation,
            "seat": None,
            "step": step,
            "shops": shops,
            "state": None,
            "usable": False,
        }
    if step is None:
        _V17_ROUTE_DEBT_REPAIR_STATE[seat] = (
            _v17_route_debt_repair_new_state()
        )
        return {
            "observation": observation,
            "seat": seat,
            "step": None,
            "shops": shops,
            "state": _V17_ROUTE_DEBT_REPAIR_STATE[seat],
            "usable": False,
        }

    state = _V17_ROUTE_DEBT_REPAIR_STATE.get(seat)
    if step == 0:
        state = _v17_route_debt_repair_new_state(
            0,
            shops is not None,
        )
        _V17_ROUTE_DEBT_REPAIR_STATE[seat] = state
    elif (
        _v17_route_debt_repair_state_is_valid(state)
        and state["continuous"]
        and state["last_step"] == step - 1
    ):
        state["last_step"] = step
    else:
        state = _v17_route_debt_repair_new_state(step, False)
        _V17_ROUTE_DEBT_REPAIR_STATE[seat] = state

    if shops is None:
        _v17_route_debt_repair_clear_payload(state)
        state["continuous"] = False
    if (
        _v17_route_debt_repair_held_is_exact(state)
        and not _v17_route_debt_repair_static80_gate(shops)
    ):
        _v17_route_debt_repair_clear_static80(state)
    if (
        state["static89_latch"]
        and not _v17_route_debt_repair_static89_gate(shops)
    ):
        state["static89_latch"] = False
    if step > _V17_ROUTE_DEBT_REPAIR_STATIC80_DUE_STEP:
        _v17_route_debt_repair_clear_static80(state)
    if step > _V17_ROUTE_DEBT_REPAIR_STATIC89_TERMINAL_STEP:
        state["static89_latch"] = False

    return {
        "observation": observation,
        "seat": seat,
        "step": step,
        "shops": shops,
        "state": state,
        "usable": bool(state["continuous"] and shops is not None),
    }


def _v17_route_debt_repair_current_context(observation):
    if not _V17_ROUTE_DEBT_REPAIR_CONTEXT:
        return None
    context = _V17_ROUTE_DEBT_REPAIR_CONTEXT[-1]
    if context.get("observation") is not observation or not context.get("usable"):
        return None
    seat = context.get("seat")
    state = context.get("state")
    if (
        seat not in (0, 1)
        or _V17_ROUTE_DEBT_REPAIR_STATE.get(seat) is not state
        or not _v17_route_debt_repair_state_is_valid(state)
        or not state["continuous"]
        or state["last_step"] != context.get("step")
    ):
        return None
    return context


def _v17_route_debt_repair_route_state(seat):
    state = _V17_ROUTE_DEBT_REPAIR_ROUTE_NAMESPACE[
        "_POST_FLOW_STATE"
    ].get(seat)
    return state if isinstance(state, dict) else None


def _v17_route_debt_repair_exact_int(value, expected):
    return (
        not isinstance(value, bool)
        and isinstance(value, int)
        and value == expected
    )


def _v17_route_debt_repair_route_has_future_debt(seat, due_step):
    state = _v17_route_debt_repair_route_state(seat)
    if state is None:
        return False
    return (
        _v17_route_debt_repair_exact_int(
            state.get("due_step"),
            due_step,
        )
        and bool(state.get("orders", []) or [])
    )


def _v17_route_debt_repair_route_was_idle(seat, last_step):
    state = _v17_route_debt_repair_route_state(seat)
    return (
        state is not None
        and _v17_route_debt_repair_exact_int(
            state.get("last_step"),
            last_step,
        )
        and _v17_route_debt_repair_exact_int(
            state.get("due_step"),
            -1,
        )
        and state.get("orders") == []
    )


def _v17_route_debt_repair_static80_capture(context):
    state = context["state"]
    seat = context["seat"]
    route_state = _v17_route_debt_repair_route_state(seat)
    if (
        context["step"] != _V17_ROUTE_DEBT_REPAIR_STATIC80_CAPTURE_STEP
        or not _v17_route_debt_repair_static80_gate(context["shops"])
        or state["static80_due_step"] != -1
        or state["static80_orders"]
        or route_state is None
        or not _v17_route_debt_repair_exact_int(
            route_state.get("last_step"),
            _V17_ROUTE_DEBT_REPAIR_STATIC80_CAPTURE_STEP,
        )
        or not _v17_route_debt_repair_exact_int(
            route_state.get("due_step"),
            _V17_ROUTE_DEBT_REPAIR_STATIC80_CAPTURE_STEP + 1,
        )
        or route_state.get("orders")
        != [_V17_ROUTE_DEBT_REPAIR_STATIC80_ORDER]
    ):
        return False
    state["static80_due_step"] = _V17_ROUTE_DEBT_REPAIR_STATIC80_DUE_STEP
    state["static80_orders"] = _V17_ROUTE_DEBT_REPAIR_COPY.deepcopy(
        route_state["orders"]
    )
    route_state["orders"] = []
    route_state["due_step"] = -1
    return True


def _v17_route_debt_repair_positive_sale(order, product):
    if not isinstance(order, list) or len(order) != 3:
        return False
    if order[0] != "SELL" or order[1] != product:
        return False
    quantity = order[2]
    return (
        not isinstance(quantity, bool)
        and isinstance(quantity, int)
        and quantity > 0
    )


def _v17_route_debt_repair_valid_pending_sale(order):
    if not isinstance(order, list) or len(order) != 3:
        return False
    if order[0] != "SELL" or order[1] not in _SELLABLE:
        return False
    quantity = order[2]
    return (
        not isinstance(quantity, bool)
        and isinstance(quantity, int)
        and quantity > 0
    )


def _v17_route_debt_repair_static89_pending_matches(route_state):
    if not isinstance(route_state, dict):
        return False
    pending = route_state.get("orders")
    if (
        not _v17_route_debt_repair_exact_int(
            route_state.get("last_step"),
            _V17_ROUTE_DEBT_REPAIR_STATIC89_ROUTE_STEP,
        )
        or not _v17_route_debt_repair_exact_int(
            route_state.get("due_step"),
            _V17_ROUTE_DEBT_REPAIR_STATIC89_ROUTE_STEP + 1,
        )
        or not isinstance(pending, list)
        or not pending
        or len(pending) > _V17_ROUTE_DEBT_REPAIR_MAX_MARKET_ORDERS
    ):
        return False
    return all(
        _v17_route_debt_repair_valid_pending_sale(order)
        for order in pending
    ) and all(
        any(
            _v17_route_debt_repair_positive_sale(order, product)
            for order in pending
        )
        for product in ("WOOL", "STRAWBERRY")
    )


def _v17_route_debt_repair_valid_market_order(order):
    if not isinstance(order, list) or not order:
        return False
    verb = order[0]
    if verb in ("HIRE", "BUY_LAND"):
        return len(order) == 1
    if len(order) != 3:
        return False
    quantity = order[2]
    if (
        isinstance(quantity, bool)
        or not isinstance(quantity, int)
        or quantity <= 0
    ):
        return False
    item = order[1]
    if verb == "SELL":
        return item in _SELLABLE
    if verb == "BUY_SEED":
        return item in _V17_ROUTE_DEBT_REPAIR_CROPS
    if verb == "BUY_PRODUCT":
        return item in _V17_ROUTE_DEBT_REPAIR_BUY_PRODUCTS
    if verb == "BUY_ANIMAL":
        return item in _V17_ROUTE_DEBT_REPAIR_ANIMALS
    return False


def _v17_route_debt_repair_market_is_well_formed(market):
    return isinstance(market, list) and all(
        _v17_route_debt_repair_valid_market_order(order)
        for order in market
    )


def _v17_route_debt_repair_noop_transition(*_args, **_kwargs):
    return None


def _v17_route_debt_repair_apply(
    observation,
    action,
    enabled,
    supported_products,
    ledger_state,
):
    context = _v17_route_debt_repair_current_context(observation)
    if context is None:
        return _V17_ROUTE_DEBT_REPAIR_PARENT_APPLY(
            observation,
            action,
            enabled,
            supported_products,
            ledger_state,
        )

    seat = context["seat"]
    step = context["step"]
    state = context["state"]
    static80_gate = _v17_route_debt_repair_static80_gate(context["shops"])
    static80_held = _v17_route_debt_repair_held_is_exact(state)
    veto_static80 = (
        static80_gate
        and static80_held
        and step in _V17_ROUTE_DEBT_REPAIR_STATIC80_VETO_STEPS
    )
    effective_enabled = False if veto_static80 else enabled

    route_had_next_debt = _v17_route_debt_repair_route_has_future_debt(
        seat,
        step + 1,
    )
    route_was_idle = _v17_route_debt_repair_route_was_idle(
        seat,
        step - 1,
    )
    static89_ready = (
        step == _V17_ROUTE_DEBT_REPAIR_STATIC89_ROUTE_STEP
        and _v17_route_debt_repair_static89_gate(context["shops"])
        and not route_had_next_debt
        and route_was_idle
    )
    market_before_shift = None
    if static89_ready:
        try:
            _seat_id, due_orders = _noclone_cycle_veto_due_orders(
                observation,
                step,
            )
            market_before_shift = _noclone_cycle_veto_market_before_shift(
                action,
                due_orders,
            )
            static89_ready = (
                _v17_route_debt_repair_market_is_well_formed(
                    market_before_shift
                )
                and len(market_before_shift)
                <= _V17_ROUTE_DEBT_REPAIR_MAX_MARKET_ORDERS
            )
        except (TypeError, ValueError, KeyError, AttributeError, IndexError):
            static89_ready = False

    repay_static80 = (
        step == _V17_ROUTE_DEBT_REPAIR_STATIC80_DUE_STEP
        and static80_gate
        and static80_held
    )
    suppress_transition = static89_ready or repay_static80
    record_transition = None
    if suppress_transition:
        record_transition = _V17_ROUTE_DEBT_REPAIR_ROUTE_NAMESPACE.get(
            "_post_flow_record_transition"
        )
        if not callable(record_transition):
            _v17_route_debt_repair_clear_payload(state)
            return _V17_ROUTE_DEBT_REPAIR_PARENT_APPLY(
                observation,
                action,
                effective_enabled,
                supported_products,
                ledger_state,
            )
        _V17_ROUTE_DEBT_REPAIR_ROUTE_NAMESPACE[
            "_post_flow_record_transition"
        ] = _v17_route_debt_repair_noop_transition

    try:
        result = _V17_ROUTE_DEBT_REPAIR_PARENT_APPLY(
            observation,
            action,
            effective_enabled,
            supported_products,
            ledger_state,
        )
    except Exception:
        _v17_route_debt_repair_clear_payload(state)
        state["continuous"] = False
        raise
    finally:
        if suppress_transition:
            _V17_ROUTE_DEBT_REPAIR_ROUTE_NAMESPACE[
                "_post_flow_record_transition"
            ] = record_transition

    if not suppress_transition:
        if (
            step == _V17_ROUTE_DEBT_REPAIR_STATIC80_CAPTURE_STEP
            and static80_gate
            and not route_had_next_debt
            and route_was_idle
        ):
            _v17_route_debt_repair_static80_capture(context)
        return result

    final = result
    try:
        route_state = _v17_route_debt_repair_route_state(seat)
        if (
            static89_ready
            and _v17_route_debt_repair_static89_pending_matches(route_state)
            and isinstance(result, dict)
            and _v17_route_debt_repair_market_is_well_formed(
                _get(result, "market", None)
            )
            and len(_get(result, "market", None))
            <= _V17_ROUTE_DEBT_REPAIR_MAX_MARKET_ORDERS
        ):
            final = _V17_ROUTE_DEBT_REPAIR_COPY.deepcopy(result)
            final["market"] = _V17_ROUTE_DEBT_REPAIR_COPY.deepcopy(
                market_before_shift
            )
            route_state["orders"] = []
            route_state["due_step"] = -1
            state["static89_latch"] = True
        elif repay_static80:
            held_orders = _V17_ROUTE_DEBT_REPAIR_COPY.deepcopy(
                state["static80_orders"]
            )
            _v17_route_debt_repair_clear_static80(state)
            market = _get(result, "market", None)
            if (
                isinstance(result, dict)
                and _v17_route_debt_repair_market_is_well_formed(market)
                and len(market) + len(held_orders)
                <= _V17_ROUTE_DEBT_REPAIR_MAX_MARKET_ORDERS
            ):
                final = _V17_ROUTE_DEBT_REPAIR_COPY.deepcopy(result)
                final["market"] = [
                    *_V17_ROUTE_DEBT_REPAIR_COPY.deepcopy(market),
                    *held_orders,
                ]
    except (TypeError, ValueError, KeyError, AttributeError, IndexError):
        final = result
        _v17_route_debt_repair_clear_payload(state)

    route_state = _v17_route_debt_repair_route_state(seat)
    if route_state is None:
        _v17_route_debt_repair_clear_payload(state)
        return result
    record_transition(
        observation,
        final,
        route_state,
        step,
    )
    return final


_noclone_cycle_veto_apply = _v17_route_debt_repair_apply


def _v17_route_debt_repair_terminal_defer(observation, action, terminal_state):
    context = _v17_route_debt_repair_current_context(observation)
    if context is None:
        return _V17_ROUTE_DEBT_REPAIR_PARENT_TERMINAL_DEFER(
            observation,
            action,
            terminal_state,
        )
    state = context["state"]
    step = context["step"]
    seat = context["seat"]
    latched = bool(state["static89_latch"])
    if step != _V17_ROUTE_DEBT_REPAIR_STATIC89_TERMINAL_STEP or not latched:
        return _V17_ROUTE_DEBT_REPAIR_PARENT_TERMINAL_DEFER(
            observation,
            action,
            terminal_state,
        )

    market = _get(action, "market", None)
    market_is_safe = (
        _v17_route_debt_repair_market_is_well_formed(market)
        and len(market) <= _V17_ROUTE_DEBT_REPAIR_MAX_MARKET_ORDERS
    )
    selected_wool = market_is_safe and any(
        _v17_route_debt_repair_positive_sale(order, "WOOL")
        for order in market
    )
    terminal_idle = (
        _v14_terminal_debt_state_is_valid(terminal_state)
        and terminal_state["due_step"] == -1
        and not terminal_state["orders"]
    )
    valid_trigger = (
        _v17_route_debt_repair_static89_gate(context["shops"])
        and _v15_breadth_cap4_inner_milk_public_farms_not_equal(observation)
        and selected_wool
        and terminal_idle
    )
    state["static89_latch"] = False
    if not valid_trigger:
        return _V17_ROUTE_DEBT_REPAIR_PARENT_TERMINAL_DEFER(
            observation,
            action,
            terminal_state,
        )
    terminal_state["orders"] = []
    terminal_state["due_step"] = -1
    _V15_BREADTH_CAP4_INNER_MILK_CURRENT_INNER.pop(seat, None)
    return action


_v14_terminal_debt_defer = _v17_route_debt_repair_terminal_defer


def _adaptive_v17_route_debt_repair_entrypoint(observation):
    """Run the frozen Round16 parent with two isolated debt repairs."""
    context = _v17_route_debt_repair_prepare_context(observation)
    _V17_ROUTE_DEBT_REPAIR_CONTEXT.append(context)
    try:
        result = _V17_ROUTE_DEBT_REPAIR_PARENT(observation)
        state = context.get("state")
        step = context.get("step")
        if isinstance(state, dict) and isinstance(step, int):
            if (
                step >= _V17_ROUTE_DEBT_REPAIR_STATIC80_DUE_STEP
                and _v17_route_debt_repair_held_is_exact(state)
            ):
                _v17_route_debt_repair_clear_static80(state)
            if step >= _V17_ROUTE_DEBT_REPAIR_STATIC89_TERMINAL_STEP:
                state["static89_latch"] = False
        return result
    except Exception:
        seat = context.get("seat")
        step = context.get("step")
        if seat in (0, 1):
            _V17_ROUTE_DEBT_REPAIR_STATE[seat] = (
                _v17_route_debt_repair_new_state(
                    step if isinstance(step, int) else -1,
                    False,
                )
            )
        raise
    finally:
        _V17_ROUTE_DEBT_REPAIR_CONTEXT.pop()

"""Repair two consumed formal regressions with exact public-state gates."""

import copy as _V18_FORMAL_REGRESSION_REPAIR_COPY


_V18_FORMAL_REGRESSION_REPAIR_PARENT = _adaptive_v17_route_debt_repair_entrypoint
_V18_FORMAL_REGRESSION_REPAIR_PARENT_APPLY = _noclone_cycle_veto_apply
_V18_FORMAL_REGRESSION_REPAIR_PARENT_SHEEP_GAP = _yarn_late_sheep_gap_prefers_second
_V18_FORMAL_REGRESSION_REPAIR_ROUTE_NAMESPACE = _V17_ROUTE_DEBT_REPAIR_ROUTE_NAMESPACE
_V18_FORMAL_REGRESSION_REPAIR_YARN_ICE = (
    "YARN_STORE",
    "ICE_CREAM_SHOP",
)
_V18_FORMAL_REGRESSION_REPAIR_DEBT_ROUTE = (
    "ICE_CREAM_SHOP",
    "YARN_STORE",
    "FARMERS_MARKET",
)
_V18_FORMAL_REGRESSION_REPAIR_STEP = 256
_V18_FORMAL_REGRESSION_REPAIR_ORDER = ["SELL", "WHEAT", 6]
_V18_FORMAL_REGRESSION_REPAIR_PRE_MARKET = (
    ("SELL", "MELON", 12),
    ("SELL", "FERTILIZER", 18),
    ("SELL", "WHEAT", 6),
)
_V18_FORMAL_REGRESSION_REPAIR_POST_MARKET = (
    ("SELL", "MELON", 12),
    ("SELL", "FERTILIZER", 18),
)
_V18_FORMAL_REGRESSION_REPAIR_ROUTE_KEYS = {
    "last_step",
    "due_step",
    "orders",
    "previous",
    "evidence",
}
_V18_FORMAL_REGRESSION_REPAIR_STATE = {}
_V18_FORMAL_REGRESSION_REPAIR_CONTEXT = []


def _v18_formal_regression_repair_exact_int(value, expected):
    return not isinstance(value, bool) and isinstance(value, int) and value == expected


def _v18_formal_regression_repair_new_state(last_step=-1, continuous=False):
    return {"last_step": last_step, "continuous": continuous}


def _v18_formal_regression_repair_state_is_valid(state):
    return (
        isinstance(state, dict)
        and set(state) == {"last_step", "continuous"}
        and not isinstance(state.get("last_step"), bool)
        and isinstance(state.get("last_step"), int)
        and state["last_step"] >= -1
        and isinstance(state.get("continuous"), bool)
    )


def _v18_formal_regression_repair_prepare_context(observation):
    seat = _v17_route_debt_repair_seat(observation)
    step = _v17_route_debt_repair_step(observation)
    shops = _v17_route_debt_repair_normalized_shops(observation)
    if seat is None:
        _V18_FORMAL_REGRESSION_REPAIR_STATE.clear()
        return {
            "observation": observation,
            "seat": None,
            "step": step,
            "shops": shops,
            "state": None,
            "usable": False,
        }
    if step is None:
        state = _v18_formal_regression_repair_new_state()
        _V18_FORMAL_REGRESSION_REPAIR_STATE[seat] = state
        return {
            "observation": observation,
            "seat": seat,
            "step": None,
            "shops": shops,
            "state": state,
            "usable": False,
        }

    state = _V18_FORMAL_REGRESSION_REPAIR_STATE.get(seat)
    if step == 0:
        state = _v18_formal_regression_repair_new_state(0, shops is not None)
        _V18_FORMAL_REGRESSION_REPAIR_STATE[seat] = state
    elif (
        _v18_formal_regression_repair_state_is_valid(state)
        and state["continuous"]
        and state["last_step"] == step - 1
    ):
        state["last_step"] = step
    else:
        state = _v18_formal_regression_repair_new_state(step, False)
        _V18_FORMAL_REGRESSION_REPAIR_STATE[seat] = state

    if shops is None:
        state["continuous"] = False
    return {
        "observation": observation,
        "seat": seat,
        "step": step,
        "shops": shops,
        "state": state,
        "usable": bool(state["continuous"] and shops is not None),
    }


def _v18_formal_regression_repair_current_context(observation):
    if not _V18_FORMAL_REGRESSION_REPAIR_CONTEXT:
        return None
    context = _V18_FORMAL_REGRESSION_REPAIR_CONTEXT[-1]
    state = context.get("state")
    seat = context.get("seat")
    if (
        context.get("observation") is not observation
        or not context.get("usable")
        or seat not in (0, 1)
        or _V18_FORMAL_REGRESSION_REPAIR_STATE.get(seat) is not state
        or not _v18_formal_regression_repair_state_is_valid(state)
        or not state["continuous"]
        or state["last_step"] != context.get("step")
    ):
        return None
    return context


def _v18_formal_regression_repair_prefers_second(observation, seat):
    parent_result = _V18_FORMAL_REGRESSION_REPAIR_PARENT_SHEEP_GAP(
        observation,
        seat,
    )
    context = _v18_formal_regression_repair_current_context(observation)
    if (
        parent_result is not True
        or isinstance(seat, bool)
        or not isinstance(seat, int)
        or seat != 1
        or context is None
        or context["seat"] != 1
    ):
        return parent_result
    if context["shops"][:2] == _V18_FORMAL_REGRESSION_REPAIR_YARN_ICE:
        return False
    return parent_result


_yarn_late_sheep_gap_prefers_second = _v18_formal_regression_repair_prefers_second


def _v18_formal_regression_repair_route_state_is_idle(state):
    return (
        isinstance(state, dict)
        and set(state) == _V18_FORMAL_REGRESSION_REPAIR_ROUTE_KEYS
        and _v18_formal_regression_repair_exact_int(
            state.get("last_step"),
            _V18_FORMAL_REGRESSION_REPAIR_STEP - 1,
        )
        and _v18_formal_regression_repair_exact_int(
            state.get("due_step"),
            -1,
        )
        and state.get("orders") == []
        and (state.get("previous") is None or isinstance(state.get("previous"), dict))
        and isinstance(state.get("evidence"), dict)
    )


def _v18_formal_regression_repair_exact_new_debt(state):
    return (
        isinstance(state, dict)
        and set(state) == _V18_FORMAL_REGRESSION_REPAIR_ROUTE_KEYS
        and _v18_formal_regression_repair_exact_int(
            state.get("last_step"),
            _V18_FORMAL_REGRESSION_REPAIR_STEP,
        )
        and _v18_formal_regression_repair_exact_int(
            state.get("due_step"),
            _V18_FORMAL_REGRESSION_REPAIR_STEP + 1,
        )
        and isinstance(state.get("orders"), list)
        and len(state["orders"]) == 1
        and _v17_route_debt_repair_exact_wheat_order(state["orders"][0])
        and (state.get("previous") is None or isinstance(state.get("previous"), dict))
        and isinstance(state.get("evidence"), dict)
    )


def _v18_formal_regression_repair_post_state_is_valid(state):
    if (
        not isinstance(state, dict)
        or set(state) != _V18_FORMAL_REGRESSION_REPAIR_ROUTE_KEYS
        or not _v18_formal_regression_repair_exact_int(
            state.get("last_step"),
            _V18_FORMAL_REGRESSION_REPAIR_STEP,
        )
        or not _v18_formal_regression_repair_exact_int(
            state.get("due_step"),
            _V18_FORMAL_REGRESSION_REPAIR_STEP + 1,
        )
        or not isinstance(state.get("orders"), list)
        or not (
            state.get("previous") is None or isinstance(state.get("previous"), dict)
        )
        or not isinstance(state.get("evidence"), dict)
    ):
        return False
    return all(
        _v17_route_debt_repair_valid_pending_sale(order) for order in state["orders"]
    )


def _v18_formal_regression_repair_exact_market(market, expected):
    if not isinstance(market, list) or len(market) != len(expected):
        return False
    for order, exact in zip(market, expected):
        if (
            not isinstance(order, list)
            or len(order) != 3
            or order[0] != exact[0]
            or order[1] != exact[1]
            or not _v18_formal_regression_repair_exact_int(order[2], exact[2])
        ):
            return False
    return True


def _v18_formal_regression_repair_noop_transition(*_args, **_kwargs):
    return None


def _v18_formal_regression_repair_apply(
    observation,
    action,
    enabled,
    supported_products,
    ledger_state,
):
    context = _v18_formal_regression_repair_current_context(observation)
    if (
        context is None
        or context["seat"] != 1
        or context["step"] != _V18_FORMAL_REGRESSION_REPAIR_STEP
        or context["shops"] != _V18_FORMAL_REGRESSION_REPAIR_DEBT_ROUTE
        or enabled is not True
    ):
        return _V18_FORMAL_REGRESSION_REPAIR_PARENT_APPLY(
            observation,
            action,
            enabled,
            supported_products,
            ledger_state,
        )

    namespace = _V18_FORMAL_REGRESSION_REPAIR_ROUTE_NAMESPACE
    post_flow_state = namespace.get("_POST_FLOW_STATE")
    route_state = post_flow_state.get(1) if isinstance(post_flow_state, dict) else None
    market_before = _get(action, "market", None)
    record_transition = namespace.get("_post_flow_record_transition")
    if (
        not _v18_formal_regression_repair_route_state_is_idle(route_state)
        or not _v18_formal_regression_repair_exact_market(
            market_before,
            _V18_FORMAL_REGRESSION_REPAIR_PRE_MARKET,
        )
        or not callable(record_transition)
    ):
        return _V18_FORMAL_REGRESSION_REPAIR_PARENT_APPLY(
            observation,
            action,
            enabled,
            supported_products,
            ledger_state,
        )

    market_before = _V18_FORMAL_REGRESSION_REPAIR_COPY.deepcopy(market_before)
    previous = route_state["previous"]
    evidence = route_state["evidence"]
    namespace["_post_flow_record_transition"] = (
        _v18_formal_regression_repair_noop_transition
    )
    try:
        result = _V18_FORMAL_REGRESSION_REPAIR_PARENT_APPLY(
            observation,
            action,
            enabled,
            supported_products,
            ledger_state,
        )
    finally:
        namespace["_post_flow_record_transition"] = record_transition

    current_state = (
        post_flow_state.get(1) if isinstance(post_flow_state, dict) else None
    )
    post_state_valid = _v18_formal_regression_repair_post_state_is_valid(current_state)
    if current_state is not route_state or not post_state_valid:
        context["state"]["continuous"] = False
        return result
    repair = (
        _v18_formal_regression_repair_exact_new_debt(route_state)
        and route_state.get("previous") is previous
        and route_state.get("evidence") is evidence
        and isinstance(result, dict)
        and _v18_formal_regression_repair_exact_market(
            _get(result, "market", None),
            _V18_FORMAL_REGRESSION_REPAIR_POST_MARKET,
        )
    )
    final = result
    if repair:
        final = _V18_FORMAL_REGRESSION_REPAIR_COPY.deepcopy(result)
        final["market"] = market_before
        route_state["orders"] = []
        route_state["due_step"] = -1

    record_transition(
        observation,
        final,
        route_state,
        _V18_FORMAL_REGRESSION_REPAIR_STEP,
    )
    return final


_noclone_cycle_veto_apply = _v18_formal_regression_repair_apply


def _adaptive_v18_formal_regression_repair_entrypoint(observation):
    """Run frozen Round 17 with two isolated regression repairs."""
    context = _v18_formal_regression_repair_prepare_context(observation)
    _V18_FORMAL_REGRESSION_REPAIR_CONTEXT.append(context)
    try:
        return _V18_FORMAL_REGRESSION_REPAIR_PARENT(observation)
    except Exception:
        seat = context.get("seat")
        step = context.get("step")
        if seat in (0, 1):
            _V18_FORMAL_REGRESSION_REPAIR_STATE[seat] = (
                _v18_formal_regression_repair_new_state(
                    step if isinstance(step, int) else -1,
                    False,
                )
            )
        raise
    finally:
        _V18_FORMAL_REGRESSION_REPAIR_CONTEXT.pop()

