def _v18_cross_family_exact_int(value, expected):
    return not isinstance(value, bool) and isinstance(value, int) and value == expected


def _v18_cross_family_exact_market(market, expected):
    if not isinstance(market, list) or len(market) != len(expected):
        return False
    for order, exact in zip(market, expected):
        if not isinstance(order, list) or len(order) != len(exact):
            return False
        for value, required in zip(order, exact):
            if isinstance(required, int):
                if not _v18_cross_family_exact_int(value, required):
                    return False
            elif value != required:
                return False
    return True


def _v18_cross_family_valid_market(market):
    return (
        isinstance(market, list)
        and len(market) <= _V17_ROUTE_DEBT_REPAIR_MAX_MARKET_ORDERS
        and _v17_route_debt_repair_market_is_well_formed(market)
    )


def _v18_cross_family_valid_action(action):
    return (
        isinstance(action, dict)
        and set(action) == {"farmer", "hands", "market"}
        and isinstance(action.get("farmer"), list)
        and isinstance(action.get("hands"), list)
        and _v18_cross_family_valid_market(action.get("market"))
    )


def _v18_cross_family_new_state(last_step=-1, continuous=False):
    return {
        "last_step": last_step,
        "continuous": continuous,
        "c_latched": False,
        "c_milk_held": False,
        "c_intercepted": False,
        "a_phase": 0,
        "b_stage": 0,
        "b_wool": 0,
    }


def _v18_cross_family_state_is_valid(state):
    return (
        isinstance(state, dict)
        and set(state)
        == {
            "last_step",
            "continuous",
            "c_latched",
            "c_milk_held",
            "c_intercepted",
            "a_phase",
            "b_stage",
            "b_wool",
        }
        and not isinstance(state.get("last_step"), bool)
        and isinstance(state.get("last_step"), int)
        and state["last_step"] >= -1
        and isinstance(state.get("continuous"), bool)
        and isinstance(state.get("c_latched"), bool)
        and isinstance(state.get("c_milk_held"), bool)
        and isinstance(state.get("c_intercepted"), bool)
        and not isinstance(state.get("a_phase"), bool)
        and isinstance(state.get("a_phase"), int)
        and 0 <= state["a_phase"] <= 3
        and not isinstance(state.get("b_stage"), bool)
        and isinstance(state.get("b_stage"), int)
        and 0 <= state["b_stage"] <= 5
        and not isinstance(state.get("b_wool"), bool)
        and isinstance(state.get("b_wool"), int)
        and state["b_wool"] in (0, 4, 12, 16)
        and (state["c_latched"] or not state["c_milk_held"])
        and (state["c_milk_held"] or not state["c_intercepted"])
        and (
            (state["b_stage"], state["b_wool"])
            in ((0, 0), (1, 0), (2, 4), (3, 12), (4, 16), (5, 0))
        )
    )


def _v18_cross_family_clear_c(state):
    state["c_latched"] = False
    state["c_milk_held"] = False
    state["c_intercepted"] = False


def _v18_cross_family_clear_a(state):
    state["a_phase"] = 0


def _v18_cross_family_clear_b(state):
    state["b_stage"] = 0
    state["b_wool"] = 0


def _v18_cross_family_disable(state):
    if _v18_cross_family_state_is_valid(state):
        state["continuous"] = False
        _v18_cross_family_clear_c(state)
        _v18_cross_family_clear_a(state)
        _v18_cross_family_clear_b(state)


def _v18_cross_family_prepare_context(observation):
    seat = _v17_route_debt_repair_seat(observation)
    step = _v17_route_debt_repair_step(observation)
    shops = _v17_route_debt_repair_normalized_shops(observation)
    if seat is None:
        _V18_CROSS_FAMILY_STATE.clear()
        return {
            "observation": observation,
            "seat": None,
            "step": step,
            "shops": shops,
            "state": None,
            "usable": False,
        }
    if step is None:
        state = _v18_cross_family_new_state()
        _V18_CROSS_FAMILY_STATE[seat] = state
        return {
            "observation": observation,
            "seat": seat,
            "step": None,
            "shops": shops,
            "state": state,
            "usable": False,
        }

    state = _V18_CROSS_FAMILY_STATE.get(seat)
    if step == 0:
        state = _v18_cross_family_new_state(0, shops is not None)
        _V18_CROSS_FAMILY_STATE[seat] = state
    elif (
        _v18_cross_family_state_is_valid(state)
        and state["continuous"]
        and state["last_step"] == step - 1
    ):
        state["last_step"] = step
    else:
        state = _v18_cross_family_new_state(step, False)
        _V18_CROSS_FAMILY_STATE[seat] = state

    if shops is None:
        _v18_cross_family_disable(state)
    prefix = shops[:3] if shops is not None else None
    if prefix != _V18_CROSS_FAMILY_C_ROUTE:
        _v18_cross_family_clear_c(state)
    if prefix != _V18_CROSS_FAMILY_A_ROUTE:
        _v18_cross_family_clear_a(state)
    if prefix != _V18_CROSS_FAMILY_B_ROUTE:
        _v18_cross_family_clear_b(state)
    if state["c_latched"] and (
        (not state["c_milk_held"] and step > 696)
        or (state["c_milk_held"] and not state["c_intercepted"] and step > 709)
        or (state["c_milk_held"] and step > 713)
    ):
        _v18_cross_family_clear_c(state)
    if state["a_phase"] and step > 713:
        _v18_cross_family_clear_a(state)
    if state["b_stage"] < 5 and step > 717:
        _v18_cross_family_clear_b(state)
    if (
        prefix == _V18_CROSS_FAMILY_B_ROUTE
        and step in _V18_CROSS_FAMILY_B_STAGES
        and state["b_stage"] != _V18_CROSS_FAMILY_B_STAGES[step]
    ):
        _v18_cross_family_disable(state)

    return {
        "observation": observation,
        "seat": seat,
        "step": step,
        "shops": shops,
        "state": state,
        "usable": bool(state["continuous"] and shops is not None),
    }


def _v18_cross_family_current_context(observation):
    if not _V18_CROSS_FAMILY_CONTEXT:
        return None
    context = _V18_CROSS_FAMILY_CONTEXT[-1]
    seat = context.get("seat")
    state = context.get("state")
    if (
        context.get("observation") is not observation
        or not context.get("usable")
        or seat not in (0, 1)
        or _V18_CROSS_FAMILY_STATE.get(seat) is not state
        or not _v18_cross_family_state_is_valid(state)
        or not state["continuous"]
        or state["last_step"] != context.get("step")
    ):
        return None
    return context


def _v18_cross_family_route_state(seat):
    states = _V18_CROSS_FAMILY_ROUTE_NAMESPACE.get("_POST_FLOW_STATE")
    state = states.get(seat) if isinstance(states, dict) else None
    return state if isinstance(state, dict) else None


def _v18_cross_family_route_state_is_valid(state, last_step):
    if (
        not isinstance(state, dict)
        or set(state) != _V18_CROSS_FAMILY_ROUTE_KEYS
        or not _v18_cross_family_exact_int(state.get("last_step"), last_step)
        or isinstance(state.get("due_step"), bool)
        or not isinstance(state.get("due_step"), int)
        or not isinstance(state.get("orders"), list)
        or not (
            state.get("previous") is None or isinstance(state.get("previous"), dict)
        )
        or not isinstance(state.get("evidence"), dict)
    ):
        return False
    return all(
        _v17_route_debt_repair_valid_pending_sale(order) for order in state["orders"]
    )


def _v18_cross_family_exact_new_wheat_debt(state):
    return (
        _v18_cross_family_route_state_is_valid(state, 256)
        and _v18_cross_family_exact_int(state.get("due_step"), 257)
        and isinstance(state.get("orders"), list)
        and len(state["orders"]) == 1
        and _v17_route_debt_repair_exact_wheat_order(state["orders"][0])
    )


def _v18_cross_family_exact_cleared_wheat_debt(state):
    return (
        _v18_cross_family_route_state_is_valid(state, 256)
        and _v18_cross_family_exact_int(state.get("due_step"), -1)
        and state.get("orders") == []
    )


def _v18_cross_family_noop_transition(*_args, **_kwargs):
    return None


def _v18_cross_family_apply(
    observation,
    action,
    enabled,
    supported_products,
    ledger_state,
):
    context = _v18_cross_family_current_context(observation)
    if (
        context is None
        or context["seat"] != 1
        or context["step"] != 256
        or context["shops"] != _V18_CROSS_FAMILY_C_ROUTE
        or enabled is not True
        or context["state"]["c_latched"]
        or context["state"]["c_milk_held"]
        or context["state"]["c_intercepted"]
        or not _v18_cross_family_valid_action(action)
        or not _v18_cross_family_exact_market(
            _get(action, "market", None),
            _V18_CROSS_FAMILY_C_PRE256,
        )
    ):
        return _V18_CROSS_FAMILY_PARENT_APPLY(
            observation,
            action,
            enabled,
            supported_products,
            ledger_state,
        )

    route_state = _v18_cross_family_route_state(1)
    if not (
        _v18_cross_family_route_state_is_valid(route_state, 255)
        and _v18_cross_family_exact_int(route_state.get("due_step"), -1)
        and route_state.get("orders") == []
    ):
        _v18_cross_family_disable(context["state"])
        return _V18_CROSS_FAMILY_PARENT_APPLY(
            observation,
            action,
            enabled,
            supported_products,
            ledger_state,
        )

    saw_exact_debt = [False]

    def probe(
        inner_observation,
        inner_action,
        inner_enabled,
        inner_supported_products,
        inner_ledger_state,
    ):
        result = _V18_CROSS_FAMILY_INNER_APPLY(
            inner_observation,
            inner_action,
            inner_enabled,
            inner_supported_products,
            inner_ledger_state,
        )
        current = _v18_cross_family_route_state(1)
        saw_exact_debt[0] = (
            current is route_state and _v18_cross_family_exact_new_wheat_debt(current)
        )
        return result

    globals()["_V18_FORMAL_REGRESSION_REPAIR_PARENT_APPLY"] = probe
    try:
        result = _V18_CROSS_FAMILY_PARENT_APPLY(
            observation,
            action,
            enabled,
            supported_products,
            ledger_state,
        )
    except Exception:
        _v18_cross_family_disable(context["state"])
        raise
    finally:
        globals()["_V18_FORMAL_REGRESSION_REPAIR_PARENT_APPLY"] = (
            _V18_CROSS_FAMILY_INNER_APPLY
        )

    current = _v18_cross_family_route_state(1)
    if (
        saw_exact_debt[0]
        and current is route_state
        and _v18_cross_family_exact_cleared_wheat_debt(current)
        and _v18_cross_family_valid_action(result)
        and _v18_cross_family_exact_market(
            _get(result, "market", None),
            _V18_CROSS_FAMILY_C_PRE256,
        )
    ):
        context["state"]["c_latched"] = True
        context["state"]["c_milk_held"] = False
        context["state"]["c_intercepted"] = False
    return result


_noclone_cycle_veto_apply = _v18_cross_family_apply


def _v18_cross_family_potential_transform(context):
    if context is None or context["seat"] != 1:
        return None
    step = context["step"]
    prefix = context["shops"][:3]
    state = context["state"]
    if prefix == _V18_CROSS_FAMILY_C_ROUTE and state["c_latched"]:
        if step == 696 and not state["c_milk_held"]:
            return "c"
        if step == 709 and state["c_milk_held"] and not state["c_intercepted"]:
            return "c"
        if step == 713 and state["c_milk_held"] and state["c_intercepted"]:
            return "c"
    if prefix == _V18_CROSS_FAMILY_A_ROUTE:
        if (step, state["a_phase"]) in ((696, 0), (709, 1), (713, 2)):
            return "a"
    if prefix == _V18_CROSS_FAMILY_B_ROUTE:
        stage_matches = (
            step in _V18_CROSS_FAMILY_B_STAGES
            and state["b_stage"] == (_V18_CROSS_FAMILY_B_STAGES[step])
        )
        creation_matches = (
            step != 576 or context["shops"] == _V18_CROSS_FAMILY_B_ROUTE_FULL
        )
        if stage_matches and creation_matches:
            return "b"
    return None


def _v18_cross_family_transform_c(observation, action, step, state):
    market = _get(action, "market", None)
    if step == 696:
        if not _v18_cross_family_exact_market(market, _V18_CROSS_FAMILY_C_696):
            return action, False
        final = _V18_CROSS_FAMILY_COPY.deepcopy(action)
        del final["market"][1]
        return final, True
    if step == 709:
        if not _v18_cross_family_exact_market(market, _V18_CROSS_FAMILY_C_709):
            return action, False
        final = _V18_CROSS_FAMILY_COPY.deepcopy(action)
        final["market"] = []
        return final, True
    if (
        not _v18_cross_family_exact_market(market, _V18_CROSS_FAMILY_C_713)
        or len(market) + 1 > _V17_ROUTE_DEBT_REPAIR_MAX_MARKET_ORDERS
    ):
        return action, False
    final = _V18_CROSS_FAMILY_COPY.deepcopy(action)
    final["market"].append(["SELL", "MILK", 6])
    return final, True


def _v18_cross_family_transform_a(observation, action, step, state):
    market = _get(action, "market", None)
    if step == 696:
        if not _v18_cross_family_exact_market(market, _V18_CROSS_FAMILY_A_696):
            return action, False
        final = _V18_CROSS_FAMILY_COPY.deepcopy(action)
        del final["market"][1]
        return final, True
    if step == 709:
        if not _v18_cross_family_exact_market(market, _V18_CROSS_FAMILY_A_709):
            return action, False
        final = _V18_CROSS_FAMILY_COPY.deepcopy(action)
        final["market"] = []
        return final, True
    if (
        not _v18_cross_family_exact_market(market, _V18_CROSS_FAMILY_A_713)
        or len(market) + 1 > _V17_ROUTE_DEBT_REPAIR_MAX_MARKET_ORDERS
    ):
        return action, False
    final = _V18_CROSS_FAMILY_COPY.deepcopy(action)
    final["market"].append(["SELL", "CARROT", 6])
    return final, True


def _v18_cross_family_transform_b(observation, action, step, state):
    market = _get(action, "market", None)
    expected = _V18_CROSS_FAMILY_B_MARKETS[step]
    if not _v18_cross_family_exact_market(market, expected):
        _v18_cross_family_disable(state)
        return action, False
    final = _V18_CROSS_FAMILY_COPY.deepcopy(action)
    if step == 576:
        final["market"].insert(1, ["SELL", "WHEAT", 7])
    elif step == 608:
        final["market"] = [["SELL", "FERTILIZER", 6]]
    elif step == 672:
        del final["market"][0]
    elif step == 713:
        del final["market"][1]
    else:
        final["market"].insert(1, ["SELL", "WOOL", 16])
    return final, True


def _v18_cross_family_commit(branch, step, state):
    if branch == "c":
        if step == 696:
            state["c_milk_held"] = True
        elif step == 709:
            state["c_intercepted"] = True
        elif step == 713:
            _v18_cross_family_clear_c(state)
    elif branch == "a":
        state["a_phase"] += 1
    else:
        state["b_stage"] += 1
        if step == 608:
            state["b_wool"] = 4
        elif step == 672:
            state["b_wool"] = 12
        elif step == 713:
            state["b_wool"] = 16
        elif step == 717:
            state["b_wool"] = 0


def _adaptive_v18_cross_family_terminal_repair_entrypoint(observation):
    """Run the frozen audited parent with exact terminal timing repairs."""
    context = _v18_cross_family_prepare_context(observation)
    _V18_CROSS_FAMILY_CONTEXT.append(context)
    state = context.get("state")
    branch = _v18_cross_family_potential_transform(
        _v18_cross_family_current_context(observation)
    )
    recorder = None
    route_state = None
    suppress = False
    if branch is not None:
        route_state = _v18_cross_family_route_state(1)
        pre_route_clock = 695 if context["step"] >= 696 else context["step"] - 1
        route_state_safe = _v18_cross_family_route_state_is_valid(
            route_state,
            pre_route_clock,
        )
        if not route_state_safe:
            _v18_cross_family_disable(state)
            branch = None
        elif branch == "a":
            recorder = _V18_CROSS_FAMILY_ROUTE_NAMESPACE.get(
                "_post_flow_record_transition"
            )
            suppress = callable(recorder)
            if not suppress:
                _v18_cross_family_disable(state)
                branch = None
    if suppress:
        _V18_CROSS_FAMILY_ROUTE_NAMESPACE["_post_flow_record_transition"] = (
            _v18_cross_family_noop_transition
        )
    try:
        action = _V18_CROSS_FAMILY_PARENT(observation)
    except Exception:
        _v18_cross_family_disable(state)
        _V18_CROSS_FAMILY_CONTEXT.pop()
        raise
    finally:
        if suppress:
            _V18_CROSS_FAMILY_ROUTE_NAMESPACE["_post_flow_record_transition"] = recorder

    try:
        if branch is None:
            return action
        current_route_state = _v18_cross_family_route_state(1)
        post_route_clock = 695 if context["step"] >= 696 else context["step"]
        if (
            current_route_state is not route_state
            or not _v18_cross_family_route_state_is_valid(
                current_route_state,
                post_route_clock,
            )
        ):
            _v18_cross_family_disable(state)
            return action
        if not _v18_cross_family_valid_action(action):
            _v18_cross_family_disable(state)
            return action
        if branch == "c":
            final, changed = _v18_cross_family_transform_c(
                observation,
                action,
                context["step"],
                state,
            )
        elif branch == "a":
            final, changed = _v18_cross_family_transform_a(
                observation,
                action,
                context["step"],
                state,
            )
        else:
            final, changed = _v18_cross_family_transform_b(
                observation,
                action,
                context["step"],
                state,
            )
        if not changed:
            if branch == "a":
                recorder(observation, action, route_state, context["step"])
            if branch == "c" and context["step"] == 713:
                _v18_cross_family_clear_c(state)
            return action
        if not _v18_cross_family_valid_market(_get(final, "market", None)):
            _v18_cross_family_disable(state)
            if branch == "a":
                recorder(observation, action, route_state, context["step"])
            return action
        if branch == "a":
            recorder(observation, final, route_state, context["step"])
        _v18_cross_family_commit(branch, context["step"], state)
        return final
    except Exception:
        _v18_cross_family_disable(state)
        raise
    finally:
        _V18_CROSS_FAMILY_CONTEXT.pop()
